  width: 112px; height: 112px; border-radius: 50%; border: 1px solid rgba(231,222,209,.16);
  background: rgba(10,7,8,.3); pointer-events: auto; touch-action: none;
}
#stickKnob {
  position: absolute; left: 50%; top: 50%; width: 46px; height: 46px; border-radius: 50%;
  transform: translate(-50%,-50%); background: rgba(231,222,209,.16); border: 1px solid rgba(231,222,209,.24);
}
#touchButtons {
  position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: max(100px, env(safe-area-inset-bottom));
  display: grid; grid-template-columns: 70px 70px; gap: 10px; pointer-events: auto;
}
#touchButtons button {
  width: 70px; height: 70px; border-radius: 50%; border: 1px solid rgba(229,43,49,.35);
  background: rgba(179,20,28,.15); color: rgba(231,222,209,.8); font-family: var(--font-mono);
  font-size: 10px; letter-spacing: .08em; touch-action: none;
}
#touchButtons button:active { background: rgba(229,43,49,.4); }
#rotateHint {
  position: absolute; left: 50%; top: 18px; transform: translateX(-50%); z-index: 25;
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .2em; color: rgba(231,222,209,.4);
