}

/* ---------- responsive ---------- */
@media (max-width: 900px) {
  #hintBar { display: none; }
  #weaponBar { bottom: 82px; }
  #bottomLeft { left: 16px; bottom: 16px; width: 200px; }
  #bottomRight { right: 16px; bottom: 14px; }
  #ammoMag { font-size: 38px; }
  #healthHead b { font-size: 18px; }
  .brand { display: none; }
  #waveHud { transform: none; margin: 0 auto; }
  #topbar { padding: 14px 16px; }
  #killFeed { position: absolute; right: 12px; top: 74px; width: 200px; }
  .kf { font-size: 8px; }
  .wave-value span { font-size: 32px; }
  .menu-content { padding-left: 0; align-items: center; text-align: center; width: 92vw; }
  .logo { font-size: clamp(64px, 18vw, 120px); }
  .menu-grad { background: radial-gradient(ellipse at 50% 46%, rgba(5,4,5,.45), rgba(5,4,5,.9) 78%); }
  .blurb { font-size: 14px; }
  .menu-actions { flex-direction: column; width: 260px; }
  .menu-meta { gap: 22px; justify-content: center; }
  .controls-grid { display: none; }
  .menu-foot { display: none; }
  .modal { padding: 28px; }
  .modal h2 { font-size: 48px; }
  #sandboxPanel { right: 10px; width: 250px; }
  #crosshair { transform: translate(-50%,-50%) scale(.85); }
}
