export class Arsenal {
  constructor() {
    this.index = 0;
    this.states = {};
    for (const d of WEAPONS) {
      this.states[d.id] = {
        mag: d.mag || 0, reserve: d.reserve || 0, cooldown: 0,
        reloading: 0, reloadTime: 0, swing: 0, hitDone: false,
        bloom: 0, pump: 0,
      };
    }
    this.lastIndex = 0;
  }

  reset() {
    for (const d of WEAPONS) {
      const s = this.states[d.id];
      s.mag = d.mag || 0; s.reserve = d.reserve || 0;
      s.cooldown = 0; s.reloading = 0; s.reloadTime = 0; s.swing = 0; s.hitDone = false; s.bloom = 0;
    }
    this.index = 0; this.lastIndex = 0;
  }

  get def() { return WEAPONS[this.index]; }
  get state() { return this.states[this.def.id]; }

  select(i) {
    i = (i + WEAPONS.length) % WEAPONS.length;
    if (i === this.index) return false;
    const d = WEAPONS[i];
    if (d.kind === 'throw' && this.states[d.id].reserve <= 0) return false;
    this.lastIndex = this.index;
    this.index = i;
    const s = this.state;
    s.reloading = 0; s.reloadTime = 0; s.swing = 0; s.cooldown = Math.max(s.cooldown, 0.12);
    return true;
  }

  cycle(dir = 1) {
    for (let k = 1; k <= WEAPONS.length; k++) {
      const i = (this.index + dir * k + WEAPONS.length * 2) % WEAPONS.length;
      if (this.select(i)) return true;
    }
    return false;
  }

  update(dt) {
    for (const s of Object.values(this.states)) {
      s.cooldown = Math.max(0, s.cooldown - dt);
      s.bloom = Math.max(0, s.bloom - dt * 2.6);
      s.pump = Math.max(0, s.pump - dt);
      if (s.reloading > 0) {
        s.reloading -= dt;
        if (s.reloading <= 0) {
          s.reloading = 0;
          const d = this.def;
          const st = this.state;
          if (d.kind === 'gun') {
            const need = d.mag - st.mag;
            const take = Math.min(need, st.reserve);
            st.mag += take; st.reserve -= take;
          }
        }
      }
      if (s.swing > 0) s.swing += dt;
    }
  }

  currentSpread(ads) {
    const d = this.def;
    const s = this.state;
    let sp = (ads ? d.adsSpread : d.spread) || 0;
    return sp + s.bloom * 0.018;
  }

  canShoot(ads) {
    const d = this.def, s = this.state;
    if (s.reloading > 0 || s.cooldown > 0) return false;
    if (d.kind === 'gun' && s.mag <= 0) return false;
    if (d.kind === 'throw' && s.reserve <= 0) return false;
    return true;
  }

  shoot(ads) {
    const d = this.def, s = this.state;
    if (!this.canShoot(ads)) return null;
    if (d.kind === 'gun') {
      s.mag--;
      s.cooldown = 60 / d.rpm;
      s.bloom = Math.min(1.4, s.bloom + (d.id === 'shotgun' ? 1 : 0.35));
      if (d.style === 'shotgun') s.pump = 0.5;
      return {
        def: d, angle: 0, spread: this.currentSpread(ads), pellets: d.pellets,
        damage: d.damage, range: d.range, recoil: d.recoil, shake: d.shake,
      };
    }
    if (d.kind === 'throw') {
      s.reserve--;
      s.cooldown = d.cooldown;
      return { def: d, thrown: true };
    }
    return null;
  }

  startMelee() {
    const d = this.def, s = this.state;
    if (d.kind !== 'melee' && d.kind !== 'saw') return null;
    if (s.cooldown > 0 || s.reloading > 0) return null;
    s.swing = 0.001; s.hitDone = false;
    s.cooldown = d.cooldown;
    if (d.kind === 'saw') return { def: d, swingId: ++s.swingId };
    return { def: d, swingId: ++s.swingId };
  }

  // Returns true exactly once during the damage window of a swing.
  consumeMeleeHit() {
    const d = this.def, s = this.state;
    if ((d.kind !== 'melee' && d.kind !== 'saw') || s.swing <= 0 || s.hitDone) return false;
    const p = s.swing / d.swing;
    const from = d.kind === 'saw' ? 0 : 0.22;
    const to = d.kind === 'saw' ? 1 : 0.62;
    if (p >= from && p <= to) { s.hitDone = true; return true; }
    return false;
  }

  meleeProgress() {
    const d = this.def, s = this.state;
    if (!(d.kind === 'melee' || d.kind === 'saw') || s.swing <= 0) return -1;
    return Math.min(1, s.swing / d.swing);
  }

  reload() {
    const d = this.def, s = this.state;
    if (d.kind !== 'gun') return false;
    if (s.reloading > 0 || s.mag >= d.mag) return false;
    if (s.reserve <= 0) return false;
    s.reloading = d.reload;
    s.reloadTime = d.reload;
    return true;
  }

  reloadProgress() {
    const s = this.state;
    if (!s.reloadTime) return 0;
    return 1 - s.reloading / s.reloadTime;
  }

  addAmmo(amount = 1) {
    for (const d of WEAPONS) {
      const s = this.states[d.id];
      if (d.kind === 'throw') s.reserve = Math.min(99, s.reserve + 2);
      else s.reserve = Math.min(d.reserve * 2, s.reserve + Math.ceil(d.reserve * 0.4 * amount));
    }
  }
}

import { rand, randInt, pick, TAU, clamp } from './util.js';

const BLOOD_COLORS = ['#6e0710', '#870b12', '#a3101a', '#5a050c', '#b51722'];

export class GoreSystem {
  constructor(worldW, worldH, groundY) {
    this.worldW = worldW;
    this.worldH = worldH;
    this.groundY = groundY;
    this.scale = 0.62;
    this.decals = document.createElement('canvas');
    this.decals.width = Math.ceil(worldW * this.scale);
    this.decals.height = Math.ceil(worldH * this.scale);
    this.dctx = this.decals.getContext('2d');
    this.dctx.scale(this.scale, this.scale);
    this.blood = [];
    this.gibs = [];
    this.casings = [];
    this.sparks = [];
    this.smoke = [];
    this.rings = [];
    this.mist = [];
    this.pools = [];
  }

  clear() {
    this.dctx.setTransform(1, 0, 0, 1, 0, 0);
    this.dctx.clearRect(0, 0, this.decals.width, this.decals.height);
    this.dctx.scale(this.scale, this.scale);
    this.blood.length = 0;
    this.gibs.length = 0;
    this.casings.length = 0;
    this.sparks.length = 0;
    this.smoke.length = 0;
    this.rings.length = 0;
    this.mist.length = 0;
    this.pools.length = 0;
  }

  bloodDrip(x, y, count = 1, spread = 18, speed = 120, opts = {}) {
    for (let i = 0; i < count; i++) {
      if (this.blood.length > 1500) this.blood.shift();
      const a = opts.angle !== undefined
        ? opts.angle + rand(spread, -spread)
        : -Math.PI / 2 + rand(spread, -spread);
      const sp = speed * rand(1.2, 0.35);
      this.blood.push({
        x: x + rand(6, -6), y: y + rand(8, -8),
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        size: (opts.size || 2.4) * rand(1.5, 0.5),
        life: rand(2.2, 0.7), max: 2.2,
        color: pick(BLOOD_COLORS),
        gore: opts.gore || 0,
      });
    }
  }

  sprayCone(x, y, angle, spread, count, speed = 500, size = 2.6) {
    for (let i = 0; i < count; i++) {
      if (this.blood.length > 1600) this.blood.shift();
      const a = angle + rand(spread, -spread);
      const sp = speed * rand(1.25, 0.2);
      this.blood.push({
        x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        size: size * rand(1.7, 0.35), life: rand(1.9, 0.35), max: 1.9,
        color: pick(BLOOD_COLORS), gore: 0.4,
      });
    }
  }

  bloodBurst(x, y, power = 400, count = 26) {
    for (let i = 0; i < count; i++) {
      if (this.blood.length > 1600) this.blood.shift();
      const a = rand(TAU);
      const sp = power * rand(1.4, 0.15);
      this.blood.push({
        x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - rand(120),
        size: rand(4.2, 0.9), life: rand(2.5, 0.6), max: 2.5,
        color: pick(BLOOD_COLORS), gore: 0.7,
      });
    }
  }

  arterial(x, y, dirAngle, strength = 1) {
    const n = 3 + Math.floor(strength * 4);
    for (let i = 0; i < n; i++) {
      const a = dirAngle + rand(0.55, -0.55);
      const sp = rand(680, 220) * strength;
      this.blood.push({
        x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        size: rand(4.5, 1.4), life: rand(1.6, 0.4), max: 1.6,
        color: pick(BLOOD_COLORS), gore: 0.9,
      });
    }
  }

  pool(x, y, radius = 30, color = '#58060d') {
    this.pools.push({ x, y, r: radius, life: 1 });
    const c = this.dctx;
    c.save();
    c.globalAlpha = 0.85;
    const g = c.createRadialGradient(x, y, 1, x, y, radius);
    g.addColorStop(0, 'rgba(78,4,11,.95)');
    g.addColorStop(0.55, 'rgba(88,6,13,.75)');
    g.addColorStop(1, 'rgba(60,3,8,0)');
    c.fillStyle = g;
    c.beginPath();
    c.ellipse(x, y, radius, radius * 0.34, 0, 0, TAU);
    c.fill();
    c.globalAlpha = 0.5;
    c.fillStyle = 'rgba(140,18,26,.5)';
    for (let i = 0; i < 5; i++) {
      c.beginPath();
      c.ellipse(x + rand(radius * 0.6, -radius * 0.6), y + rand(6, -6), rand(6, 2), rand(3, 1), 0, 0, TAU);
      c.fill();
    }
    c.restore();
  }

  splat(x, y, radius, angle = 0, alpha = 0.9) {
    const c = this.dctx;
    c.save();
    c.globalAlpha = alpha;
    c.fillStyle = pick(BLOOD_COLORS);
    const n = 4 + (radius / 5 | 0);
    c.beginPath();
    for (let i = 0; i < n; i++) {
      const a = rand(TAU), r = rand(radius, radius * 0.25);
      const px = x + Math.cos(a) * r, py = y + Math.sin(a) * r * 0.6;
      c.moveTo(px + rand(5, 2), py);
      c.arc(px, py, rand(5, 2), 0, TAU);
    }
    c.fill();
    // droplets trailing opposite the travel direction
    for (let i = 0; i < 5; i++) {
      const d = rand(radius * 2.6, radius);
      c.beginPath();
      c.arc(x + Math.cos(angle + Math.PI) * d + rand(6, -6), y + Math.sin(angle + Math.PI) * d * 0.4 + rand(4, -4), rand(3.2, 0.8), 0, TAU);
      c.fill();
    }
    // specks
    for (let i = 0; i < 7; i++) {
      c.beginPath();
      c.arc(x + rand(radius * 3, -radius * 3), y + rand(radius * 1.1, -radius * 1.1), rand(1.8, 0.5), 0, TAU);
      c.fill();
    }
    c.restore();
  }

  decalWound(x, y, size = 4) {
    const c = this.dctx;
    c.save();
    c.fillStyle = 'rgba(40,2,5,.85)';
    c.beginPath(); c.arc(x, y, size, 0, TAU); c.fill();
    c.fillStyle = 'rgba(150,20,28,.8)';
    c.beginPath(); c.arc(x + size * 0.5, y + size * 0.5, size * 0.5, 0, TAU); c.fill();
    c.restore();
  }

  gib(x, y, vx, vy, size, color = '#8a5c4c', opts = {}) {
    if (this.gibs.length > 120) this.gibs.shift();
    this.gibs.push({
      x, y, vx, vy, size, color,
      rot: rand(TAU), vr: rand(14, -14),
      life: opts.life || rand(14, 6), max: 14,
      bone: opts.bone || false,
      rest: false, bounces: 0,
      stretch: 1,
    });
  }

  boneShard(x, y, vx, vy, size = 7) {
    if (this.gibs.length > 130) this.gibs.shift();
    this.gibs.push({
      x, y, vx, vy, size, color: '#d8cbae', rot: rand(TAU), vr: rand(18, -18),
      life: 14, max: 14, bone: true, rest: false, bounces: 0, stretch: 1.6,
    });
  }

  casing(x, y, dir, angle) {
    if (this.casings.length > 90) this.casings.shift();
    this.casings.push({
      x, y, vx: Math.cos(angle + dir * rand(1.5, 0.7)) * rand(260, 90),
      vy: Math.sin(angle) * 80 - rand(320, 140),
      rot: rand(TAU), vr: rand(26, -26), life: 6, rest: false,
    });
  }

  spark(x, y, nx, ny, count = 8, color = '#ffd08a') {
    for (let i = 0; i < count; i++) {
      this.sparks.push({
        x, y,
        vx: (nx + rand(0.9, -0.9)) * rand(520, 80),
        vy: (ny + rand(0.9, -0.9)) * rand(520, 80) - 40,
        life: rand(0.6, 0.15), max: 0.6, color,
      });
    }
  }

  dust(x, y, count = 5, size = 8, color = 'rgba(150,140,125,') {
    for (let i = 0; i < count; i++) {
      this.smoke.push({
        x: x + rand(10, -10), y: y + rand(8, -8),
        vx: rand(90, -90), vy: rand(-20, -90),
        r: size * rand(1.6, 0.5), life: rand(1.3, 0.4), max: 1.3,
        color, grow: rand(34, 10),
      });
      if (this.smoke.length > 160) this.smoke.shift();
    }
  }

  shockwave(x, y, radius = 260) {
    this.rings.push({ x, y, r: 6, max: radius, life: 1, maxLife: 1 });
  }

  bloodMist(x, y, radius = 40) {
    for (let i = 0; i < 6; i++) {
      this.mist.push({
        x: x + rand(radius, -radius) * 0.5, y: y + rand(radius, -radius) * 0.5,
        r: radius * rand(0.8, 0.25), life: rand(0.9, 0.3), max: 0.9,
        vx: rand(40, -40), vy: rand(-10, -50), color: 'rgba(120,8,16,',
      });
    }
  }

  update(dt) {
    const gy = this.groundY;
    const blood = this.blood;
    for (let i = blood.length - 1; i >= 0; i--) {
      const b = blood[i];
      b.vy += 2100 * dt;
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life -= dt;
      if (b.y >= gy + rand(4, -1)) {
        // floor splat
        if (Math.abs(b.vx) + Math.abs(b.vy) > 130) this.splat(b.x, gy + rand(1, -1), clamp(b.size * 1.9, 1.6, 9), Math.atan2(b.vy, b.vx), 0.85);
        blood.splice(i, 1);
        continue;
      }
      if (b.y > this.worldH || b.life <= 0 || b.x < -20 || b.x > this.worldW + 20) blood.splice(i, 1);
    }

    for (let i = this.gibs.length - 1; i >= 0; i--) {
      const g = this.gibs[i];
      g.life -= dt;
      if (!g.rest) {
        g.vy += 2000 * dt;
        g.x += g.vx * dt;
        g.y += g.vy * dt;
        g.rot += g.vr * dt;
        if (g.y > gy - g.size * 0.3) {
          g.y = gy - g.size * 0.3;
          if (g.vy > 220 && g.bounces < 2) {
            g.vy *= -0.32; g.vx *= 0.6; g.vr *= 0.5; g.bounces++;
            this.splat(g.x, gy, g.size * 1.3, rand(TAU), 0.7);
            this.bloodDrip(g.x, g.y, 2, 1.2, 80);
          } else {
            g.vy = 0; g.vx *= 0.75; g.vr *= 0.7;
            if (Math.abs(g.vx) < 20) { g.rest = true; g.vx = 0; g.vr = 0; }
          }
        }
      }
      if (g.life <= 0) this.gibs.splice(i, 1);
    }

    for (let i = this.casings.length - 1; i >= 0; i--) {
      const c = this.casings[i];
      c.life -= dt;
      if (!c.rest) {
        c.vy += 1900 * dt;
        c.x += c.vx * dt; c.y += c.vy * dt; c.rot += c.vr * dt;
        if (c.y > gy - 1) {
          c.y = gy - 1;
          if (Math.abs(c.vy) > 90) { c.vy *= -0.35; c.vx *= 0.6; c.vr *= 0.6; }
          else { c.vy = 0; c.vx *= 0.8; c.vr *= 0.5; if (Math.abs(c.vx) < 8) c.rest = true; }
        }
      }
      if (c.life <= 0) this.casings.splice(i, 1);
    }

    for (let i = this.sparks.length - 1; i >= 0; i--) {
      const s = this.sparks[i];
      s.life -= dt; s.vy += 1600 * dt;
      s.x += s.vx * dt; s.y += s.vy * dt;
      if (s.life <= 0 || s.y > gy) this.sparks.splice(i, 1);
    }
    for (let i = this.smoke.length - 1; i >= 0; i--) {
      const s = this.smoke[i];
      s.life -= dt; s.x += s.vx * dt; s.y += s.vy * dt;
      s.vx *= 0.97; s.vy *= 0.97; s.r += s.grow * dt;
      if (s.life <= 0) this.smoke.splice(i, 1);
    }
    for (let i = this.mist.length - 1; i >= 0; i--) {
      const m = this.mist[i];
      m.life -= dt; m.x += m.vx * dt; m.y += m.vy * dt; m.r += 30 * dt;
      if (m.life <= 0) this.mist.splice(i, 1);
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt * 1.6; r.r += (r.max - r.r) * dt * 5;
      if (r.life <= 0) this.rings.splice(i, 1);
    }
  }

  drawDecals(ctx) {
    ctx.drawImage(this.decals, 0, 0, this.worldW, this.worldH);
  }

  drawBehind(ctx) {
    // pools glisten under characters
    for (const p of this.pools) {
      ctx.save();
      ctx.globalAlpha = 0.22;
      const g = ctx.createRadialGradient(p.x, p.y - 2, 1, p.x, p.y - 2, p.r);
      g.addColorStop(0, 'rgba(255,120,120,.5)');
      g.addColorStop(1, 'rgba(255,120,120,0)');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.ellipse(p.x, p.y, p.r * 1.25, p.r * 0.4, 0, 0, TAU); ctx.fill();
      ctx.restore();
    }
  }

  draw(ctx) {
    // mist
    for (const m of this.mist) {
      const a = Math.max(0, m.life / m.max) * 0.25;
      ctx.fillStyle = m.color + a.toFixed(3) + ')';
      ctx.beginPath(); ctx.arc(m.x, m.y, m.r, 0, TAU); ctx.fill();
    }
    // blood droplets (streak + drop)
    for (const b of this.blood) {
      const a = Math.min(1, b.life * 2.2);
      ctx.strokeStyle = b.color;
      ctx.globalAlpha = a * 0.85;
      ctx.lineWidth = Math.max(1, b.size * 0.9);
      ctx.beginPath();
      ctx.moveTo(b.x - b.vx * 0.014, b.y - b.vy * 0.014);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
      ctx.globalAlpha = a;
      ctx.fillStyle = b.color;
      ctx.beginPath(); ctx.arc(b.x, b.y, b.size * 0.62, 0, TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;

    for (const g of this.gibs) {
      ctx.save();
      ctx.translate(g.x, g.y); ctx.rotate(g.rot);
      const a = Math.min(1, g.life * 1.5);
      ctx.globalAlpha = a;
      ctx.fillStyle = g.color;
      if (g.bone) {
        ctx.fillRect(-g.size * 0.9, -g.size * 0.22, g.size * 1.8, g.size * 0.44);
        ctx.fillStyle = 'rgba(120,20,20,.65)';
        ctx.fillRect(-g.size * 0.9, -g.size * 0.22, g.size * 1.8, g.size * 0.16);
      } else {
        ctx.beginPath();
        ctx.ellipse(0, 0, g.size, g.size * 0.72, 0, 0, TAU);
        ctx.fill();
        ctx.fillStyle = 'rgba(150,24,30,.55)';
        ctx.beginPath(); ctx.arc(g.size * 0.3, -g.size * 0.2, g.size * 0.35, 0, TAU); ctx.fill();
        ctx.fillStyle = 'rgba(40,4,6,.4)';
        ctx.beginPath(); ctx.arc(-g.size * 0.25, g.size * 0.18, g.size * 0.3, 0, TAU); ctx.fill();
      }
      ctx.restore();
    }
    ctx.globalAlpha = 1;

    for (const c of this.casings) {
      ctx.save();
      ctx.translate(c.x, c.y); ctx.rotate(c.rot);
      ctx.fillStyle = '#c49b4e';
      ctx.fillRect(-3.5, -1.2, 7, 2.4);
      ctx.fillStyle = '#7d5c25';
      ctx.fillRect(-3.5, -1.2, 2, 2.4);
      ctx.restore();
    }

    for (const s of this.sparks) {
      const a = Math.max(0, s.life / s.max);
      ctx.strokeStyle = s.color; ctx.globalAlpha = a;
      ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.moveTo(s.x, s.y); ctx.lineTo(s.x - s.vx * 0.02, s.y - s.vy * 0.02); ctx.stroke();
    }
    ctx.globalAlpha = 1;

    for (const s of this.smoke) {
      const a = Math.max(0, s.life / s.max);
      ctx.fillStyle = s.color + (a * 0.32).toFixed(3) + ')';
      ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, TAU); ctx.fill();
    }

    for (const r of this.rings) {
      ctx.strokeStyle = `rgba(255,190,120,${(r.life * 0.4).toFixed(3)})`;
      ctx.lineWidth = 2 + r.life * 4;
      ctx.beginPath(); ctx.arc(r.x, r.y, r.r, 0, TAU); ctx.stroke();
      ctx.strokeStyle = `rgba(180,30,30,${(r.life * 0.3).toFixed(3)})`;
      ctx.beginPath(); ctx.arc(r.x, r.y, r.r * 0.72, 0, TAU); ctx.stroke();
    }
  }
}

import { clamp, rand, TAU } from './util.js';

export const LINKS = [
  ['spine', 'hip', 'neck', 16, 1],
  ['neck', 'neck', 'head', 14, 1],
  ['clavL', 'neck', 'shoulderL', 9, 0.9],
  ['clavR', 'neck', 'shoulderR', 9, 0.9],
  ['sideL', 'hip', 'shoulderL', 13, 0.75],
  ['sideR', 'hip', 'shoulderR', 13, 0.75],
  ['upperArmL', 'shoulderL', 'elbowL', 8, 1],
  ['foreArmL', 'elbowL', 'handL', 6.5, 1],
  ['upperArmR', 'shoulderR', 'elbowR', 8, 1],
  ['foreArmR', 'elbowR', 'handR', 6.5, 1],
  ['thighL', 'hip', 'kneeL', 10, 1],
  ['shinL', 'kneeL', 'footL', 7.5, 1],
  ['thighR', 'hip', 'kneeR', 10, 1],
  ['shinR', 'kneeR', 'footR', 7.5, 1],
];

// Which physical link disappears when a hit severs a body part.
export const SEVER_LINKS = {
  head: ['neck'],
  armL: ['upperArmL'],
  armR: ['upperArmR'],
  handL: ['foreArmL'],
  handR: ['foreArmR'],
  legL: ['thighL'],
  legR: ['thighR'],
  shinL: ['shinL'],
  shinR: ['shinR'],
};

export const RADII = {
  hip: 10, neck: 9, head: 15, shoulderL: 8, shoulderR: 8,
  elbowL: 6, elbowR: 6, handL: 5.5, handR: 5.5,
  kneeL: 7, kneeR: 7, footL: 6, footR: 6,
};

export class Ragdoll {
  constructor(pose, opts = {}) {
    this.worldW = opts.worldW || 4000;
    this.groundY = opts.groundY ?? 700;
    this.points = {};
    for (const name of Object.keys(pose)) {
      const p = pose[name];
      this.points[name] = {
        x: p.x, y: p.y, px: p.x - rand(1.4, -1.4), py: p.y - rand(1.4, -1.4),
        r: RADII[name] || 7, ground: 0,
      };
    }
    this.links = LINKS.map(([name, a, b, r, stiff]) => ({
      name, a, b, r, stiff, cut: false,
      rest: Math.hypot(this.points[a].x - this.points[b].x, this.points[a].y - this.points[b].y),
      hidden: false,
    }));
    this.time = 0;
    this.drag = 0.996;
  }

  pose() {
    const out = {};
    for (const name of Object.keys(this.points)) {
      const p = this.points[name];
      out[name] = { x: p.x, y: p.y };
    }
    return out;
  }

  cutBone(key) {
    const names = SEVER_LINKS[key];
    if (!names) return false;
    let did = false;
    for (const l of this.links) {
      if (names.includes(l.name) && !l.cut) { l.cut = true; did = true; }
      if (key === 'armL' && (l.name === 'clavL' || l.name === 'sideL')) l.cut = true;
      if (key === 'armR' && (l.name === 'clavR' || l.name === 'sideR')) l.cut = true;
    }
    return did;
  }

  point(name) { return this.points[name]; }

  impulse(px, py, ix, iy, falloff = 1) {
    for (const p of Object.values(this.points)) {
      const d = Math.hypot(p.x - px, p.y - py);
      const f = clamp(1 - d / 150, 0, 1) * falloff;
      p.px -= ix * f; p.py -= iy * f;
    }
  }

  update(dt) {
    this.time += dt;
    const steps = dt > 0.022 ? 2 : 1;
    const sub = dt / steps;
    for (let s = 0; s < steps; s++) this.step(sub);
  }

  step(dt) {
    const g = 2100;
    const pts = this.points;
    const gy = this.groundY;
    for (const p of Object.values(pts)) {
      const vx = (p.x - p.px) * this.drag;
      const vy = (p.y - p.py) * this.drag;
      p.px = p.x; p.py = p.y;
      p.x += vx;
      p.y += vy + g * dt * dt;
      p.ground = Math.max(0, p.ground - dt * 4);
      // ground
      if (p.y > gy - p.r) {
        p.y = gy - p.r;
        const impact = Math.max(0, p.y - p.py);
        p.py = p.y + Math.min(8, impact * 0.4);
        p.x = p.px + (p.x - p.px) * 0.62;
        p.ground = 1;
      }
      if (p.x < p.r + 4) { p.x = p.r + 4; p.px = p.x + 3; }
      if (p.x > this.worldW - p.r - 4) { p.x = this.worldW - p.r - 4; p.px = p.x - 3; }
    }

    // constraints
    for (let it = 0; it < 7; it++) {
      for (const l of this.links) {
        if (l.cut) continue;
        const a = pts[l.a], b = pts[l.b];
        let dx = b.x - a.x, dy = b.y - a.y;
        const d = Math.hypot(dx, dy) || 0.001;
        const diff = (d - l.rest) / d;
        const k = 0.5 * l.stiff;
        const ox = dx * diff * k, oy = dy * diff * k;
        if (a.ground > 0.5 && b.ground < 0.5) {
          b.x -= ox * 1.6; b.y -= oy * 1.6;
        } else if (b.ground > 0.5 && a.ground < 0.5) {
          a.x += ox * 1.6; a.y += oy * 1.6;
        } else {
          a.x += ox; a.y += oy; b.x -= ox; b.y -= oy;
        }
      }
    }
    // keep bodies out of floor after solve
    for (const p of Object.values(pts)) {
      if (p.y > gy - p.r) p.y = gy - p.r;
    }
  }
}

import { clamp, rand, chance, pick, TAU, raySeg, dist, lerp } from './util.js';
import { Ragdoll, RADII } from './ragdoll.js';
import { drawActor, drawActorCorpse } from './actorDraw.js';

export const GROUND = 700;
const SKIN = ['#c99a7e', '#a9765c', '#8a5a45', '#d8ab8c', '#6f4636'];
const SHIRT = ['#3d4347', '#4a3f37', '#2e3a3a', '#52443c', '#38393f', '#5a4a3b', '#26343b'];
const SHIRT_ENEMY = ['#3a3d34', '#46352e', '#2c3134', '#44392f', '#353a31'];
const PANTS = ['#2b2c30', '#33302a', '#262a30', '#3a342c', '#212429'];

const PART_MULT = { head: 3.4, torso: 1, armL: 0.62, armR: 0.62, handL: 0.5, handR: 0.5, legL: 0.72, legR: 0.72, shinL: 0.62, shinR: 0.62 };
const PART_THRESH = { head: 62, armL: 64, armR: 64, handL: 48, handR: 48, legL: 92, legR: 92, shinL: 74, shinR: 74 };

export function buildPose(a) {
  const t = a.time;
  const f = a.facing;
  const aim = a.aim;
  const run = a.state === 'run';
  const moving = Math.abs(a.vx) > 15;
  const cyc = a.walkPhase;
  const breath = Math.sin(t * 2.1 + a.id) * 0.9;
  const bob = moving ? Math.abs(Math.sin(cyc)) * (run ? 3.4 : 1.8) : breath;
  const hipX = a.x + (moving ? Math.cos(cyc) * 1.6 : 0);
  const hipY = a.y - 88 - bob + a.crouch;
  const hip = { x: hipX, y: hipY };
  const lean = moving ? f * 4 : 0;
  const neck = { x: hipX + lean + Math.cos(aim) * 2, y: hipY - 47 + breath * 0.5 };
  const head = { x: neck.x + Math.cos(aim) * 3.5, y: neck.y - 28 + a.headDrop };

  const shoulderFront = { x: neck.x + 5 * f, y: neck.y + 7 };
  const shoulderBack = { x: neck.x - 5 * f, y: neck.y + 9 };
  const dir = { x: Math.cos(aim), y: Math.sin(aim) };
  const perp = { x: -dir.y, y: dir.x };

  let handFront, handBack, elbowFront, elbowBack, swingAngle = aim;
  const holding = a.weaponDef && (a.weaponDef.kind === 'gun' || a.weaponDef.kind === 'throw');
  let meleeP = a.meleeProgress;

  if (holding) {
    const kick = a.recoilKick || 0;
    const reach = 44 - kick * 8;
    handFront = {
      x: shoulderFront.x + dir.x * reach + perp.x * 3,
      y: shoulderFront.y + dir.y * reach + perp.y * 3,
    };
    handBack = {
      x: handFront.x - dir.x * 17 + perp.x * 5,
      y: handFront.y - dir.y * 17 + perp.y * 5,
    };
    elbowFront = {
      x: shoulderFront.x + dir.x * reach * 0.48 + perp.x * 9,
      y: shoulderFront.y + dir.y * reach * 0.48 + perp.y * 9,
    };
    elbowBack = {
      x: shoulderBack.x + dir.x * reach * 0.4 - perp.x * 4,
      y: shoulderBack.y + dir.y * reach * 0.4 - perp.y * 4,
    };
  } else {
    const isSaw = a.weaponDef && a.weaponDef.kind === 'saw';
    if (meleeP >= 0) {
      const eased = 1 - Math.pow(1 - meleeP, 2);
      swingAngle = aim + (isSaw ? 0 : (eased - 0.42) * 2.5) * f;
      const reach = 46 + (isSaw ? 4 : Math.sin(meleeP * Math.PI) * 10);
      const sd = { x: Math.cos(swingAngle), y: Math.sin(swingAngle) };
      handFront = { x: shoulderFront.x + sd.x * reach, y: shoulderFront.y + sd.y * reach };
      handBack = { x: handFront.x - sd.x * 15 + 6 * f, y: handFront.y - sd.y * 15 + 6 };
      elbowFront = { x: shoulderFront.x + sd.x * reach * 0.5, y: shoulderFront.y + sd.y * reach * 0.5 - 2 };
      elbowBack = { x: shoulderBack.x + sd.x * reach * 0.3, y: shoulderBack.y + sd.y * reach * 0.3 };
    } else {
      const hang = Math.sin(t * 1.6 + a.id) * 1.5;
      handFront = { x: shoulderFront.x + 4 * f + hang, y: shoulderFront.y + 42 };
      handBack = { x: shoulderBack.x - 2 * f, y: shoulderBack.y + 44 };
      elbowFront = { x: shoulderFront.x + 3 * f, y: shoulderFront.y + 22 };
      elbowBack = { x: shoulderBack.x - 3 * f, y: shoulderBack.y + 23 };
    }
  }

  // legs
  const stride = moving ? (run ? 24 : 15) : 3;
  const lift = moving ? (run ? 12 : 7) : 0;
  const swingA = Math.sin(cyc), swingB = Math.sin(cyc + Math.PI);
  const kneeL = {
    x: hipX - 9 + swingA * stride * 0.55,
    y: hipY + 44 - Math.max(0, swingB) * lift * 0.4,
  };
  const footL = {
    x: hipX - 9 + swingA * stride,
    y: a.y - Math.max(0, swingB) * lift - 2,
  };
  const kneeR = {
    x: hipX + 9 + swingB * stride * 0.55,
    y: hipY + 44 - Math.max(0, swingA) * lift * 0.4,
  };
  const footR = {
    x: hipX + 9 + swingB * stride,
    y: a.y - Math.max(0, swingA) * lift - 2,
  };
  if (!a.onGround) {
    kneeL.y -= 10; footL.y = a.y - 16 + swingA * 4;
    kneeR.y -= 6; footR.y = a.y - 10 + swingB * 4;
  }

  return {
    hip, neck, head,
    shoulderL: shoulderBack, shoulderR: shoulderFront,
    elbowL: elbowBack, elbowR: elbowFront,
    handL: handBack, handR: handFront,
    kneeL, kneeR, footL, footR,
    aim, swingAngle, dir, perp,
  };
}

export class Actor {
  constructor(opts = {}) {
    this.id = Math.random() * 1000;
    this.x = opts.x ?? 600;
    this.y = opts.y ?? GROUND;
    this.vx = 0; this.vy = 0;
    this.type = opts.type || 'dummy';
    this.isPlayer = this.type === 'player';
    this.facing = opts.facing || 1;
    this.aim = opts.aim ?? (this.facing > 0 ? 0 : Math.PI);
    this.alive = true;
    this.maxHp = opts.hp || (this.isPlayer ? 100 : this.type === 'enemy' ? 100 : 120);
    this.hp = this.maxHp;
    this.time = rand(10);
    this.walkPhase = rand(TAU);
    this.state = 'idle';
    this.onGround = true;
    this.crouch = 0;
    this.headDrop = 0;
    this.recoilKick = 0;
    this.meleeProgress = -1;
    this.hitFlash = 0;
    this.deadTime = 0;
    this.ragdoll = null;
    this.pose = null;
    this.totalDamage = 0;
    this.limbsLost = 0;
    this.partDamage = {};
    this.wounds = [];
    this.bleeders = [];
    this.skin = opts.skin || pick(SKIN);
    this.shirt = opts.shirt || (this.type === 'enemy' ? pick(SHIRT_ENEMY) : pick(SHIRT));
    this.pants = opts.pants || pick(PANTS);
    this.hair = pick(['#1f1a17', '#2c211a', '#3a2a1e', '#141110', '#4b3826']);
    this.helmet = opts.helmet ?? (this.type === 'enemy' && chance(0.35));
    this.mask = opts.mask ?? (this.type === 'enemy' && chance(0.4));
    this.weaponDef = opts.weapon || null;
    this.weaponLevel = opts.weaponLevel || 0;
    this.enemyType = opts.enemyType || 'grunt';
    this.bleed = 1;
    this.gore = opts.gore || null;
    this.audio = opts.audio || null;
    this.worldW = opts.worldW || 4000;
    this.groundY = opts.groundY ?? GROUND;
    this.onDeath = null;
    this.onKillFeed = null;
    this.stun = 0;
    this.attackCd = 0;
    this.aimTarget = opts.aim ?? this.aim;
    this.walkSpeed = 0;
    this.dropped = false;
    this.pose = buildPose(this);
  }

  get height() { return 178; }

  update(dt) {
    this.time += dt;
    this.hitFlash = Math.max(0, this.hitFlash - dt * 5);
    this.recoilKick = Math.max(0, this.recoilKick - dt * 9);
    this.stun = Math.max(0, this.stun - dt);
    this.attackCd = Math.max(0, this.attackCd - dt);

    if (this.alive) {
      const speed = Math.abs(this.vx);
      this.state = speed > 25 ? 'run' : 'idle';
      this.walkPhase += dt * (4.6 + speed * 0.022) * (this.vx < 0 ? -1 : 1) * (speed > 25 ? 1 : 0.25);
      if (this.walkPhase > TAU * 10) this.walkPhase -= TAU * 10;
      this.crouch = lerp(this.crouch, 0, dt * 8);
      this.headDrop = lerp(this.headDrop, 0, dt * 8);
      this.facing = Math.cos(this.aim) >= 0 ? 1 : -1;
      this.pose = buildPose(this);

      // alive bleeding from wounds
      if (this.hp < this.maxHp * 0.55 && chance(dt * 2.4) && this.gore) {
        const w = this.wounds.length ? pick(this.wounds) : null;
        const p = w ? this.partPos(w.part) : this.pose.hip;
        this.gore.bloodDrip(p.x, p.y, 1, 0.7, 50, { size: 1.6 });
      }
    } else {
      this.deadTime += dt;
      if (this.ragdoll) {
        this.ragdoll.update(dt);
        this.pose = this.ragdoll.pose();
        this.pose.aim = this.aim;
        this.pose.dir = { x: Math.cos(this.aim), y: Math.sin(this.aim) };
        this.pose.perp = { x: -Math.sin(this.aim), y: Math.cos(this.aim) };
        // arterial fountains from stumps
        for (const b of this.bleeders) {
          b.ttl -= dt;
          b.acc += dt;
          if (b.ttl > 0 && b.acc > b.rate && this.gore) {
            b.acc = 0;
            const p = this.pose[b.point];
            if (p) {
              const a = -Math.PI / 2 + rand(1.2, -1.2);
              this.gore.arterial(p.x, p.y, a, clamp(b.ttl / b.maxTtl, 0.2, 1) * b.power);
              if (chance(0.35)) this.gore.bloodDrip(p.x, p.y, 1, 1.4, 60, { size: 2 });
            }
          }
        }
        // slow pool growth under corpse
        if (this.deadTime < 12 && this.gore) {
          this.poolAcc = (this.poolAcc || 0) + dt;
          if (this.poolAcc > 0.55) {
            this.poolAcc = 0;
            const hip = this.pose.hip;
            const size = 16 + Math.min(30, this.deadTime * 2.4);
            if (chance(0.5)) this.gore.pool(hip.x, this.groundY - 3, size);
          }
        }
      }
    }

    // wounds fade
    for (let i = this.wounds.length - 1; i >= 0; i--) {
      this.wounds[i].life -= dt;
      if (this.wounds[i].life <= 0) this.wounds.splice(i, 1);
    }
  }

  partPos(part) {
    const p = this.pose;
    if (!p) return { x: this.x, y: this.y - 100 };
    switch (part) {
      case 'head': return p.head;
      case 'torso': return { x: (p.hip.x + p.neck.x) / 2, y: (p.hip.y + p.neck.y) / 2 };
      case 'armL': return p.elbowL;
      case 'armR': return p.elbowR;
      case 'handL': return p.handL;
      case 'handR': return p.handR;
      case 'legL': return p.kneeL;
      case 'legR': return p.kneeR;
      case 'shinL': return p.footL;
      case 'shinR': return p.footR;
      default: return p.hip;
    }
  }

  // Capsule segments used for hit detection
  hitSegments() {
    const p = this.pose || buildPose(this);
    const list = [
      { part: 'torso', ax: p.hip.x, ay: p.hip.y, bx: p.neck.x, by: p.neck.y, r: 16 },
      { part: 'torso', ax: p.hip.x, ay: p.hip.y, bx: p.shoulderL.x, by: p.shoulderL.y, r: 11 },
      { part: 'torso', ax: p.hip.x, ay: p.hip.y, bx: p.shoulderR.x, by: p.shoulderR.y, r: 11 },
      { part: 'head', ax: p.head.x, ay: p.head.y - 2, bx: p.head.x, by: p.head.y, r: 16 },
      { part: 'armL', ax: p.shoulderL.x, ay: p.shoulderL.y, bx: p.elbowL.x, by: p.elbowL.y, r: 6.5 },
      { part: 'armR', ax: p.shoulderR.x, ay: p.shoulderR.y, bx: p.elbowR.x, by: p.elbowR.y, r: 6.5 },
      { part: 'handL', ax: p.elbowL.x, ay: p.elbowL.y, bx: p.handL.x, by: p.handL.y, r: 5.5 },
      { part: 'handR', ax: p.elbowR.x, ay: p.elbowR.y, bx: p.handR.x, by: p.handR.y, r: 5.5 },
      { part: 'legL', ax: p.hip.x, ay: p.hip.y, bx: p.kneeL.x, by: p.kneeL.y, r: 9 },
      { part: 'legR', ax: p.hip.x, ay: p.hip.y, bx: p.kneeR.x, by: p.kneeR.y, r: 9 },
      { part: 'shinL', ax: p.kneeL.x, ay: p.kneeL.y, bx: p.footL.x, by: p.footL.y, r: 7.5 },
      { part: 'shinR', ax: p.kneeR.x, ay: p.kneeR.y, bx: p.footR.x, by: p.footR.y, r: 7.5 },
    ];
    if (!this.alive) {
      for (const l of list) {
        if (l.part === 'head' && this.ragdoll?.links.find(x => x.name === 'neck')?.cut) l.dead = true;
      }
    }
    return list;
  }

  rayHit(ox, oy, dx, dy, maxDist = 3000, allowDead = true) {
    if (!this.alive && !allowDead) return null;
    let best = null;
    for (const s of this.hitSegments()) {
      if (s.dead) continue;
      const t = raySeg(ox, oy, dx, dy, s.ax, s.ay, s.bx, s.by, s.r);
      if (t !== null && t <= maxDist && (!best || t < best.t)) {
        best = { t, x: ox + dx * t, y: oy + dy * t, part: s.part, actor: this };
      }
    }
    return best;
  }

  takeDamage(amount, part, x, y, dirAngle, force = 500, opts = {}) {
    if (!this.alive) {
      this.hitCorpse(x, y, dirAngle, force * 0.55, amount);
      return { dead: true, corpse: true };
    }
    const mult = PART_MULT[part] || 1;
    const dmg = amount * mult;
    this.hp -= dmg;
    this.totalDamage += dmg;
    this.hitFlash = 1;
    this.partDamage[part] = (this.partDamage[part] || 0) + dmg;
    this.stun = Math.max(this.stun, opts.stun || 0.12);
    this.recoilKick = Math.min(1, (this.recoilKick || 0) + 0.3);

    // spray blood out the far side
    if (this.gore) {
      const outAngle = dirAngle + (chance(0.5) ? 0 : Math.PI);
      this.gore.sprayCone(x, y, outAngle, 0.5, 4 + Math.min(14, dmg * 0.25 | 0), 180 + dmg * 4, 2.2);
      if (chance(0.5)) this.gore.bloodDrip(x, y, 2, 1.1, 120, { size: 2.2 });
      if (dmg > 8) this.gore.decalWound(x, this.groundY - 1, rand(3, 1.5) + dmg * 0.03);
    }
    this.wounds.push({
      part, u: rand(0.7, 0.3), side: rand(1, -1),
      off: rand(5, -5), size: 2 + clamp(dmg * 0.08, 0, 7), life: 25,
    });

    const isHead = part === 'head';
    const canSever = ['head', 'armL', 'armR', 'handL', 'handR', 'legL', 'legR', 'shinL', 'shinR'].includes(part);
    const severPower = opts.sever || 0;
    const acc = this.partDamage[part];
    const threshold = PART_THRESH[part] || 999;
    const shouldSever = canSever && this.hp > -this.maxHp * 1.4 && (
      (isHead && dmg > 70) ||
      (severPower > 0 && acc > threshold * (0.65 + rand(0.3))) ||
      (dmg > 55 && chance(0.18))
    );

    let severed = null;
    if (shouldSever) severed = part;

    this.bleed = clamp(1 - this.hp / this.maxHp, 0, 1);

    if (this.hp <= 0) {
      this.die({ x, y, dirAngle, force, severed, part, headExplode: isHead && (dmg > 85 || opts.explodeHead) });
      return { dead: true, severed, part };
    }
    if (severed) {
      this.die({ x, y, dirAngle, force: force * 0.7, severed, part, survivable: true });
      return { dead: true, severed, part };
    }
    if (this.audio) {
      if (isHead) this.audio.flesh(true);
      else if (chance(0.5)) this.audio.flesh(dmg > 30);
    }
    return { dead: false, severed, part };
  }

  die(info = {}) {
    if (!this.alive) return;
    this.alive = false;
    this.deadTime = 0;
    this.hp = Math.min(0, this.hp);
    this.state = 'dead';
    const pose = buildPose(this);
    this.ragdoll = new Ragdoll(pose, { worldW: this.worldW, groundY: this.groundY });
    if (info.severed) {
      const key = info.severed;
      this.ragdoll.cutBone(key);
      this.limbsLost++;
      const p = this.ragdoll.points[this.stumpPoint(key)];
      if (p) {
        this.bleeders.push({ point: this.stumpPoint(key), ttl: rand(9, 4), maxTtl: 9, acc: 0, rate: rand(0.035, 0.012), power: rand(1.4, 0.7) });
        if (this.gore) {
          this.gore.arterial(p.x, p.y, -Math.PI / 2 + rand(0.9, -0.9), 1.6);
          this.gore.bloodMist(p.x, p.y, 34);
        }
        if (this.audio) this.audio.squelch();
      }
    } else {
      this.bleeders.push({ point: 'neck', ttl: rand(4, 1.5), maxTtl: 4, acc: 0, rate: rand(0.1, 0.05), power: 0.5 });
    }
    if (info.headExplode) {
      const hp = this.ragdoll.points.head;
      this.ragdoll.cutBone('head');
      if (this.gore && hp) {
        this.gore.bloodBurst(hp.x, hp.y, 520, 40);
        this.gore.bloodMist(hp.x, hp.y, 60);
        for (let i = 0; i < 12; i++) {
          this.gore.gib(hp.x, hp.y, rand(520, -520), rand(-220, -620), rand(9, 3), pick(['#7a4030', '#8e5a44', '#a2654a']), { bone: i < 3 });
        }
        this.gore.boneShard(hp.x, hp.y, rand(300, -300), rand(-300, -600), 8);
      }
      if (this.audio) this.audio.headPop();
    } else if (this.audio) {
      this.audio.death();
    }
    // death impulse
    if (this.ragdoll && info.force) {
      const ix = Math.cos(info.dirAngle) * info.force * 0.014;
      const iy = Math.sin(info.dirAngle) * info.force * 0.014 - 3;
      this.ragdoll.impulse(info.x || this.x, info.y || this.y - 100, ix, iy, 1.4);
    }
    if (this.gore) {
      this.gore.pool(this.x, this.groundY - 3, rand(26, 16));
      this.gore.bloodBurst(this.x, this.y - 95, 260, 12);
    }
    if (this.audio) this.audio.grunt();
    if (this.onDeath) this.onDeath(this, info);
  }

  stumpPoint(key) {
    return { head: 'neck', armL: 'shoulderL', armR: 'shoulderR', handL: 'elbowL', handR: 'elbowR', legL: 'kneeL', legR: 'kneeR', shinL: 'kneeL', shinR: 'kneeR' }[key] || 'neck';
  }

  hitCorpse(x, y, dirAngle, force, amount = 0) {
    if (this.gore) {
      this.gore.sprayCone(x, y, dirAngle, 0.7, 3 + Math.min(8, amount * 0.1 | 0), 130, 2.4);
      this.gore.bloodDrip(x, y, 2, 1.4, 100, { size: 2 });
    }
    if (this.ragdoll) {
      this.ragdoll.impulse(x, y, Math.cos(dirAngle) * force * 0.012, Math.sin(dirAngle) * force * 0.012, 1.1);
    }
    if (amount > 60 && this.gore && chance(0.5)) {
      this.gore.gib(x, y, Math.cos(dirAngle) * 200, -rand(200, 60), rand(7, 3), '#8a5a44', { bone: chance(0.2) });
    }
  }

  draw(ctx) {
    if (this.alive) drawActor(ctx, this);
    else drawActorCorpse(ctx, this);
  }
}

import { clamp, lerp, noise1, TAU, pick } from './util.js';

const BLOOD = '#7c0a11';

function shade(hex, amt) {
  if (!hex) return '#444';
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  r = clamp(Math.round(r + 255 * amt), 0, 255);
  g = clamp(Math.round(g + 255 * amt), 0, 255);
  b = clamp(Math.round(b + 255 * amt), 0, 255);
  return `rgb(${r},${g},${b})`;
}

function limb(ctx, a, b, w, fill, outline = 'rgba(8,6,6,.62)', hi = null) {
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  ctx.strokeStyle = outline; ctx.lineWidth = w + 2.6;
  ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
  ctx.strokeStyle = fill; ctx.lineWidth = w;
  ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
  if (hi) {
    const dx = b.x - a.x, dy = b.y - a.y, l = Math.hypot(dx, dy) || 1;
    const ox = -dy / l * w * 0.2, oy = dx / l * w * 0.2;
    ctx.strokeStyle = hi; ctx.lineWidth = w * 0.26; ctx.globalAlpha = 0.6;
    ctx.beginPath(); ctx.moveTo(a.x + ox, a.y + oy); ctx.lineTo(b.x + ox, b.y + oy); ctx.stroke();
    ctx.globalAlpha = 1;
  }
}

function shadow(ctx, x, y, w, alpha = 0.42) {
  const g = ctx.createRadialGradient(x, y, 2, x, y, w);
  g.addColorStop(0, `rgba(0,0,0,${alpha})`);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.ellipse(x, y, w, w * 0.24, 0, 0, TAU); ctx.fill();
}

function partSegments(actor) {
  const p = actor.pose;
  if (!p) return {};
  return {
    head: [p.head, p.head],
    torso: [p.hip, p.neck],
    armL: [p.shoulderL, p.elbowL],
    armR: [p.shoulderR, p.elbowR],
    handL: [p.elbowL, p.handL],
    handR: [p.elbowR, p.handR],
    legL: [p.hip, p.kneeL],
    legR: [p.hip, p.kneeR],
    shinL: [p.kneeL, p.footL],
    shinR: [p.kneeR, p.footR],
  };
}

function drawWounds(ctx, a) {
  const segs = partSegments(a);
  for (const w of a.wounds) {
    const seg = segs[w.part];
    if (!seg) continue;
    const [p1, p2] = seg;
    const x = lerp(p1.x, p2.x, w.u) + w.side * 3;
    const y = lerp(p1.y, p2.y, w.u) + w.off * 0.4;
    const ang = Math.atan2(p2.y - p1.y, p2.x - p1.x);
    ctx.save();
    ctx.translate(x, y); ctx.rotate(ang);
    ctx.fillStyle = 'rgba(42,3,5,.75)';
    ctx.beginPath(); ctx.ellipse(0, 0, w.size * 0.65, w.size * 0.95, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(160,22,28,.55)';
    ctx.beginPath(); ctx.ellipse(-w.size * 0.15, -w.size * 0.1, w.size * 0.4, w.size * 0.55, 0, 0, TAU); ctx.fill();
    ctx.restore();
    if (w.size > 4 && Math.sin(a.time * 2 + w.u * 20) > 0.2) {
      ctx.strokeStyle = 'rgba(110,8,14,.55)';
      ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.moveTo(x, y + w.size * 0.5); ctx.lineTo(x + 1, y + w.size * 2.1); ctx.stroke();
    }
  }
}

function drawBloodSpatter(ctx, a) {
  const blood = clamp(1 - a.hp / a.maxHp, 0, 1);
  if (blood < 0.08) return;
  const n = Math.floor(blood * 22);
  ctx.save();
  for (let i = 0; i < n; i++) {
    const s = noise1(a.id * 7 + i * 3.1);
    const t = noise1(a.id * 3 + i * 1.7);
    const p = a.pose;
    const ax = lerp(p.hip.x, p.neck.x, s), ay = lerp(p.hip.y, p.neck.y, s);
    const x = ax + (t - 0.5) * 26, y = ay + (s - 0.3) * 30;
    ctx.fillStyle = `rgba(${96 + t * 50 | 0},${6 + t * 12 | 0},${10 + t * 6 | 0},${0.25 + blood * 0.5})`;
    ctx.beginPath();
    ctx.ellipse(x, y, 1.5 + t * 3.2, 1 + s * 3.4, s * 3, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawHead(ctx, a, hx, hy, angle, dead = false) {
  const skin = a.skin;
  const f = a.facing;
  ctx.save();
  ctx.translate(hx, hy);
  ctx.rotate(angle);
  // skull / jaw
  ctx.beginPath();
  ctx.ellipse(0, 0, 12.5, 15.5, 0, 0, TAU);
  ctx.fillStyle = dead ? '#b08a72' : skin;
  ctx.fill();
  ctx.strokeStyle = 'rgba(10,7,6,.55)'; ctx.lineWidth = 1.6; ctx.stroke();
  // ear
  ctx.fillStyle = shade(skin, -0.1);
  ctx.beginPath(); ctx.ellipse(-f * 10, 1, 3.2, 5, 0, 0, TAU); ctx.fill();
  // hair / helmet
  if (a.helmet) {
    ctx.beginPath();
    ctx.ellipse(0, -5, 15, 12, 0, Math.PI, TAU);
    ctx.fillStyle = '#363b37'; ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.09)';
    ctx.beginPath(); ctx.ellipse(-3, -9, 8, 3.5, -0.2, 0, TAU); ctx.fill();
    ctx.strokeStyle = '#20241f'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-14, -3); ctx.quadraticCurveTo(0, 2, 14, -3); ctx.stroke();
  } else {
    ctx.beginPath();
    ctx.arc(0, -3, 13.5, Math.PI * 1.05, Math.PI * 2.0);
    ctx.fillStyle = a.hair; ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.06)';
    ctx.beginPath(); ctx.arc(-4, -7, 7, Math.PI, Math.PI * 1.7); ctx.fill();
  }
  if (a.mask) {
    ctx.beginPath();
    ctx.ellipse(f * 1.5, 7, 11, 8.5, 0, 0, TAU);
    ctx.fillStyle = '#22221f'; ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.05)';
    ctx.beginPath(); ctx.ellipse(f * 1.5, 5, 8, 3, 0, 0, TAU); ctx.fill();
  }
  // face details
  ctx.fillStyle = dead ? 'rgba(30,10,10,.8)' : 'rgba(24,14,12,.9)';
  ctx.beginPath(); ctx.ellipse(f * 3.5, -1.5, 1.9, 1.2, 0, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(f * 8.5, -1, 1.2, 1, 0, 0, TAU); ctx.fill();
  // nose
  ctx.strokeStyle = shade(skin, -0.18); ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(f * 9, 1); ctx.lineTo(f * 12.5, 5); ctx.lineTo(f * 10, 6); ctx.stroke();
  // mouth / blood
  ctx.strokeStyle = dead ? 'rgba(70,4,8,.9)' : 'rgba(80,30,26,.55)';
  ctx.lineWidth = 1.3;
  ctx.beginPath(); ctx.moveTo(f * 8, 10); ctx.lineTo(f * 12, 10); ctx.stroke();
  if (a.hp < a.maxHp * 0.5 && !dead) {
    ctx.strokeStyle = 'rgba(130,10,16,.6)'; ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(f * 9, 6); ctx.lineTo(f * 10, 13); ctx.stroke();
  }
  ctx.restore();
}

function drawTorso(ctx, a, p) {
  const hip = p.hip, neck = p.neck;
  const dx = neck.x - hip.x, dy = neck.y - hip.y;
  const l = Math.hypot(dx, dy) || 1;
  const nx = -dy / l, ny = dx / l;
  const wh = 16, wn = 23;
  const shirt = a.shirt;
  ctx.beginPath();
  ctx.moveTo(hip.x + nx * wh, hip.y + ny * wh);
  ctx.quadraticCurveTo(
    (hip.x + neck.x) / 2 + nx * (wn + 5) - dx * 0.05,
    (hip.y + neck.y) / 2 + ny * (wn + 5) - dy * 0.05,
    neck.x + nx * wn, neck.y + ny * wn,
  );
  ctx.lineTo(neck.x - nx * wn, neck.y - ny * wn);
  ctx.quadraticCurveTo(
    (hip.x + neck.x) / 2 - nx * (wn + 4), (hip.y + neck.y) / 2 - ny * (wn + 4),
    hip.x - nx * wh, hip.y - ny * wh,
  );
  ctx.closePath();
  const g = ctx.createLinearGradient(hip.x + nx * 20, hip.y, hip.x - nx * 20, hip.y);
  g.addColorStop(0, shade(shirt, 0.11));
  g.addColorStop(0.45, shirt);
  g.addColorStop(1, shade(shirt, -0.18));
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = 'rgba(8,6,6,.6)'; ctx.lineWidth = 2.2; ctx.stroke();

  // vest / straps
  if (a.type === 'enemy' && !a.mask) {
    ctx.fillStyle = 'rgba(20,20,18,.35)';
    ctx.beginPath();
    ctx.ellipse((hip.x + neck.x) / 2, (hip.y + neck.y) / 2, 13, 20, Math.atan2(dy, dx) + Math.PI / 2, 0, TAU);
    ctx.fill();
  }
  // belt
  ctx.strokeStyle = '#1c1917'; ctx.lineWidth = 6; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(hip.x + nx * wh, hip.y + ny * wh); ctx.lineTo(hip.x - nx * wh, hip.y - ny * wh); ctx.stroke();
  ctx.strokeStyle = '#8c7550'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(hip.x + nx * 4, hip.y + ny * 4); ctx.lineTo(hip.x + nx * 4, hip.y + ny * 4 + 3); ctx.stroke();
  // folds
  ctx.strokeStyle = 'rgba(0,0,0,.16)'; ctx.lineWidth = 1.1;
  for (let i = 0; i < 3; i++) {
    const t = 0.3 + i * 0.17;
    const x = lerp(hip.x, neck.x, t), y = lerp(hip.y, neck.y, t);
    ctx.beginPath(); ctx.moveTo(x - nx * 8, y - ny * 8); ctx.lineTo(x + nx * 7, y + ny * 7); ctx.stroke();
  }
  // player armband
  if (a.isPlayer) {
    ctx.fillStyle = 'rgba(160,20,26,.8)';
    ctx.beginPath(); ctx.ellipse(neck.x + nx * 20, neck.y + ny * 5, 4, 8, Math.atan2(dy, dx) + Math.PI / 2, 0, TAU); ctx.fill();
  }
}

export function weaponMuzzle(def, hand, angle) {
  const len = def.style === 'shotgun' ? 62 : def.style === 'rifle' ? 58 : def.style === 'smg' ? 42 : def.style === 'pistol' ? 30 : 0;
  return { x: hand.x + Math.cos(angle) * len, y: hand.y + Math.sin(angle) * len };
}

export function drawWeapon(ctx, def, hand, angle, opts = {}) {
  if (!def) return;
  ctx.save();
  ctx.translate(hand.x, hand.y);
  ctx.rotate(angle + (opts.tilt || 0));
  const recoil = opts.recoil || 0;
  ctx.translate(-recoil * 5, 0);
  const g = 1;
  const dark = '#17191a';
  const metal = '#5e6668';
  const metalHi = '#9aa4a6';
  if (def.style === 'pistol') {
    ctx.fillStyle = '#2a2c2c'; ctx.strokeStyle = '#0c0d0e'; ctx.lineWidth = 1;
    ctx.fillRect(2, -3, 27, 6); ctx.strokeRect(2, -3, 27, 6);
    ctx.fillStyle = metal; ctx.fillRect(20, -2.5, 9, 3);
    ctx.fillStyle = def.color; ctx.fillRect(4, -4, 15, 3);
    ctx.save(); ctx.translate(4, 3); ctx.rotate(0.32);
    ctx.fillStyle = '#392a20'; ctx.fillRect(-3, -1, 8, 13); ctx.strokeRect(-3, -1, 8, 13);
    ctx.fillStyle = '#191410'; ctx.fillRect(-2, 8, 6, 2);
    ctx.restore();
    ctx.fillStyle = '#141516'; ctx.fillRect(9, 5, 3, 6);
    ctx.fillStyle = '#d4cba9'; ctx.fillRect(24, -4, 2, 2);
  } else if (def.style === 'shotgun') {
    ctx.fillStyle = '#4a3a29'; ctx.fillRect(-15, -2, 22, 9);
    ctx.fillStyle = '#5f482f'; ctx.fillRect(-16, 1, 10, 7);
    ctx.fillStyle = '#2c2f30'; ctx.fillRect(5, -3.5, 56, 6);
    ctx.fillStyle = '#3d4142'; ctx.fillRect(14, 1, 28, 4);
    ctx.fillStyle = '#1d1f20'; ctx.fillRect(56, -4, 7, 5);
    ctx.fillStyle = '#8a7454'; ctx.fillRect(34, 1, 9, 5);
    ctx.fillStyle = '#191b1c'; ctx.fillRect(4, 2, 4, 9);
    if (opts.pump) {
      ctx.fillStyle = '#7d6444'; ctx.fillRect(14 - opts.pump * 8, 2, 14, 5);
    }
  } else if (def.style === 'smg' || def.style === 'rifle') {
    const len = def.style === 'rifle' ? 52 : 38;
    ctx.fillStyle = '#1a1d1e'; ctx.fillRect(-8, -4, 14, 10);
    ctx.fillStyle = def.color; ctx.fillRect(-2, -4, len, 7);
    ctx.fillStyle = 'rgba(255,255,255,.1)'; ctx.fillRect(-2, -4, len, 2);
    ctx.fillStyle = '#101213'; ctx.fillRect(len * 0.45, 2, 9, 11);
    ctx.fillStyle = '#2c3031'; ctx.fillRect(len * 0.45, 2, 9, 3);
    if (def.style === 'rifle') {
      ctx.fillStyle = '#202324'; ctx.fillRect(8, -7, 14, 4);
      ctx.fillStyle = '#0f1112'; ctx.fillRect(12, -10, 5, 4);
      ctx.fillStyle = '#3a3f40'; ctx.fillRect(-8, 2, 10, 4);
    } else {
      ctx.fillStyle = '#2d3132'; ctx.fillRect(5, -7, 6, 3);
      ctx.fillStyle = '#101213'; ctx.fillRect(7, -9, 2, 2);
    }
    ctx.fillStyle = '#282b2c'; ctx.fillRect(len - 6, -2.5, 12, 4);
    ctx.fillStyle = '#0d0f10'; ctx.fillRect(len + 5, -3.5, 4, 4);
  } else if (def.style === 'katana') {
    ctx.save();
    ctx.rotate(opts.swing || 0);
    // handle
    ctx.fillStyle = '#1a1a1c';
    ctx.fillRect(-16, -2.5, 20, 5);
    ctx.fillStyle = 'rgba(180,40,40,.55)';
    for (let i = -14; i < 2; i += 4) ctx.fillRect(i, -2.5, 2, 5);
    ctx.fillStyle = '#8f8267'; ctx.fillRect(3, -5, 4, 10);
    // blade
    const grad = ctx.createLinearGradient(6, 0, 90, 0);
    grad.addColorStop(0, '#b9c4c6'); grad.addColorStop(0.5, '#f4f2ea'); grad.addColorStop(1, '#8d9a9e');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(7, -3);
    ctx.quadraticCurveTo(52, -5.5, 91, -1.5);
    ctx.lineTo(90, 2.4);
    ctx.quadraticCurveTo(50, 0.5, 7, 3);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,.6)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(10, -1); ctx.quadraticCurveTo(55, -2.6, 88, 0); ctx.stroke();
    ctx.restore();
  } else if (def.style === 'sledge') {
    ctx.save();
    ctx.rotate(opts.swing || 0);
    ctx.fillStyle = '#6b4f33';
    ctx.fillRect(-14, -2.5, 62, 5);
    ctx.fillStyle = '#3e2c1d';
    ctx.fillRect(-14, -2.5, 10, 5);
    ctx.fillStyle = '#4e5355';
    ctx.fillRect(42, -12, 20, 24);
    ctx.fillStyle = '#6d7476';
    ctx.fillRect(42, -12, 20, 7);
    ctx.fillStyle = '#26292a'; ctx.fillRect(43, -9, 4, 18);
    ctx.restore();
  } else if (def.style === 'chainsaw') {
    ctx.fillStyle = '#a5401c'; ctx.fillRect(-14, -8, 30, 16);
    ctx.fillStyle = '#d5813c'; ctx.fillRect(-12, -6, 10, 4);
    ctx.fillStyle = '#2e3031'; ctx.fillRect(12, -5, 38, 10);
    ctx.fillStyle = '#777d7c'; ctx.fillRect(48, -7, 6, 14);
    ctx.strokeStyle = '#9ba1a0'; ctx.lineWidth = 1;
    for (let i = 0; i < 12; i++) {
      ctx.beginPath(); ctx.moveTo(12 + i * 3.4, -5); ctx.lineTo(14 + i * 3.4, -7); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(12 + i * 3.4, 5); ctx.lineTo(14 + i * 3.4, 7); ctx.stroke();
    }
    ctx.fillStyle = '#1c1d1e'; ctx.fillRect(-8, 6, 6, 8);
  } else if (def.style === 'grenade') {
    ctx.fillStyle = '#4a5136';
    ctx.beginPath(); ctx.arc(8, 0, 7, 0, TAU); ctx.fill();
    ctx.strokeStyle = '#252a1c'; ctx.lineWidth = 1;
    for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.moveTo(8, -7); ctx.lineTo(8, 7); ctx.stroke(); }
    ctx.fillStyle = '#8d8f7a'; ctx.fillRect(6, -10, 4, 4);
  }
  ctx.restore();
}

export function drawMuzzleFlash(ctx, x, y, angle, intensity = 1) {
  if (intensity <= 0) return;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(0, 0, 1, 0, 0, 60 * intensity);
  g.addColorStop(0, `rgba(255,240,190,${0.9 * intensity})`);
  g.addColorStop(0.25, `rgba(255,190,80,${0.55 * intensity})`);
  g.addColorStop(1, 'rgba(255,120,20,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, 60 * intensity, 0, TAU); ctx.fill();
  ctx.fillStyle = `rgba(255,238,190,${0.9 * intensity})`;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(30 * intensity, -8 * intensity);
  ctx.lineTo(20 * intensity, 0);
  ctx.lineTo(32 * intensity, 7 * intensity);
  ctx.closePath(); ctx.fill();
  ctx.restore();
}

export function drawActor(ctx, a) {
  const p = a.pose;
  if (!p) return;
  const hipY = Math.max(p.hip.y, p.footL.y, p.footR.y);
  shadow(ctx, a.x, a.y, 44, 0.45);

  const backArmCol = shade(a.shirt, -0.26);
  const frontArmCol = a.shirt;
  const skinBack = shade(a.skin, -0.2);

  // back limbs
  limb(ctx, p.hip, p.kneeL, 13, shade(a.pants, -0.16));
  limb(ctx, p.kneeL, p.footL, 10, shade(a.pants, -0.22));
  drawBoot(ctx, p.footL, shade(a.pants, -0.5), -a.facing);
  limb(ctx, p.shoulderL, p.elbowL, 11, backArmCol);
  limb(ctx, p.elbowL, p.handL, 8.5, skinBack);

  // front leg
  limb(ctx, p.hip, p.kneeR, 14, shade(a.pants, 0.02));
  limb(ctx, p.kneeR, p.footR, 10.5, shade(a.pants, -0.08));
  drawBoot(ctx, p.footR, shade(a.pants, -0.4), a.facing);

  drawTorso(ctx, a, p);
  // neck
  limb(ctx, p.neck, p.head, 9, a.skin, 'rgba(8,6,6,.4)');

  // weapon + front arm
  const angle = a.weaponDef && (a.weaponDef.kind === 'gun' || a.weaponDef.kind === 'throw') ? p.aim : (p.swingAngle ?? p.aim);
  const swing = 0;
  if (a.weaponDef) drawWeapon(ctx, a.weaponDef, p.handR, angle, { recoil: a.recoilKick, swing, pump: a.pumpAnim || 0 });
  limb(ctx, p.shoulderR, p.elbowR, 12, frontArmCol);
  limb(ctx, p.elbowR, p.handR, 9, a.skin);
  // hands
  ctx.fillStyle = a.skin;
  ctx.beginPath(); ctx.arc(p.handR.x, p.handR.y, 5.2, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(p.handL.x, p.handL.y, 4.8, 0, TAU); ctx.fill();

  drawHead(ctx, a, p.head.x, p.head.y, Math.atan2(p.head.y - p.neck.y, p.head.x - p.neck.x) + Math.PI / 2);
  drawBloodSpatter(ctx, a);
  drawWounds(ctx, a);

  // muzzle flash
  if (a.muzzleFlash > 0 && a.weaponDef) {
    const def = a.weaponDef;
    const m = weaponMuzzle(def, p.handR, angle);
    drawMuzzleFlash(ctx, m.x, m.y, angle, clamp(a.muzzleFlash * 14, 0, 1));
  }

  if (a.hitFlash > 0.35) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = (a.hitFlash - 0.35) * 0.18;
    ctx.fillStyle = '#ff3a30';
    ctx.beginPath(); ctx.arc(p.neck.x, p.neck.y + 24, 34, 0, TAU); ctx.fill();
    ctx.restore();
  }
}

function drawBoot(ctx, foot, color, dir) {
  ctx.save();
  ctx.translate(foot.x, foot.y);
  ctx.rotate(0);
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.ellipse(dir * 2, 1, 10, 5.5, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,.4)';
  ctx.beginPath(); ctx.ellipse(-dir * 3, 2, 6, 3, 0, 0, TAU); ctx.fill();
  ctx.restore();
}

export function drawActorCorpse(ctx, a) {
  const p = a.pose;
  if (!p) return;
  const r = a.ragdoll;
  const cut = name => r ? r.links.find(l => l.name === name)?.cut : false;
  const hipY = Math.max(p.hip.y, p.footL.y, p.footR.y);
  shadow(ctx, p.hip.x, a.groundY, 54, 0.4);

  // pooled blood under corpse drawn by gore
  const pants = shade(a.pants, -0.06);
  const shirt = shade(a.shirt, -0.1);
  const skin = shade(a.skin, -0.12);

  if (!cut('thighL')) { limb(ctx, p.hip, p.kneeL, 13, shade(pants, -0.15)); if (!cut('shinL')) { limb(ctx, p.kneeL, p.footL, 10, shade(pants, -0.2)); drawBoot(ctx, p.footL, shade(pants, -0.5), -1); } else stump(ctx, p.kneeL, 6); }
  if (!cut('upperArmL')) { limb(ctx, p.shoulderL, p.elbowL, 11, shade(shirt, -0.3)); if (!cut('foreArmL')) limb(ctx, p.elbowL, p.handL, 8, shade(skin, -0.2)); else stump(ctx, p.elbowL, 5); }

  if (!cut('spine')) drawTorso(ctx, { ...a, shirt }, p);

  if (!cut('thighR')) { limb(ctx, p.hip, p.kneeR, 13.5, pants); if (!cut('shinR')) { limb(ctx, p.kneeR, p.footR, 10.5, shade(pants, -0.06)); drawBoot(ctx, p.footR, shade(pants, -0.44), 1); } else stump(ctx, p.kneeR, 6); }

  if (!cut('neck')) {
    limb(ctx, p.neck, p.head, 9, skin);
    drawHead(ctx, a, p.head.x, p.head.y, Math.atan2(p.head.y - p.neck.y, p.head.x - p.neck.x) + Math.PI / 2, true);
  } else {
    stump(ctx, p.neck, 7);
    drawHead(ctx, a, p.head.x, p.head.y, a.aim + Math.PI / 2 + a.deadTime * 0.4, true);
  }

  if (!cut('upperArmR')) {
    limb(ctx, p.shoulderR, p.elbowR, 12, shade(shirt, 0.03));
    if (!cut('foreArmR')) {
      limb(ctx, p.elbowR, p.handR, 9, skin);
      if (a.weaponDef) {
        const angle = Math.atan2(p.handR.y - p.elbowR.y, p.handR.x - p.elbowR.x);
        drawWeapon(ctx, a.weaponDef, p.handR, angle, { recoil: 0 });
      }
    } else stump(ctx, p.elbowR, 5);
  } else stump(ctx, p.shoulderR, 6);

  drawBloodSpatter(ctx, a);
  drawWounds(ctx, a);

  // cut stumps on detached piece roots
  for (const l of r ? r.links : []) {
    if (!l.cut) continue;
    const bp = p[l.b];
    if (bp) stump(ctx, bp, l.name.includes('Arm') || l.name.includes('thigh') ? 5 : 3);
  }
}

function stump(ctx, pt, size = 6) {
  if (!pt) return;
  ctx.save();
  const g = ctx.createRadialGradient(pt.x, pt.y, 0, pt.x, pt.y, size * 1.8);
  g.addColorStop(0, 'rgba(120,12,18,.95)');
  g.addColorStop(0.55, 'rgba(84,6,11,.85)');
  g.addColorStop(1, 'rgba(60,3,8,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(pt.x, pt.y, size * 1.8, 0, TAU); ctx.fill();
  ctx.fillStyle = 'rgba(180,70,62,.9)';
  ctx.beginPath(); ctx.arc(pt.x, pt.y, size * 0.55, 0, TAU); ctx.fill();
  ctx.fillStyle = 'rgba(225,205,175,.7)';
  ctx.beginPath(); ctx.arc(pt.x - 1, pt.y - 1, size * 0.22, 0, TAU); ctx.fill();
  ctx.restore();
}

import { rand, TAU, clamp, noise1, pick } from './util.js';

export const WORLD_W = 4200;
export const GROUND_Y = 700;
export const WALL_TOP = -420;

export class World {
  constructor() {
    this.w = WORLD_W;
    this.ground = GROUND_Y;
    this.lamps = [
      { x: 220, y: -110, hue: 30, flicker: 0.2 },
      { x: 900, y: -125, hue: 26, flicker: 0.9 },
      { x: 1580, y: -105, hue: 32, flicker: 0.1 },
      { x: 2270, y: -130, hue: 22, flicker: 1.4 },
      { x: 2960, y: -110, hue: 30, flicker: 0.4 },
      { x: 3680, y: -120, hue: 27, flicker: 1.0 },
    ];
    this.dust = Array.from({ length: 110 }, () => ({
      x: rand(this.w), y: rand(820, -300), z: rand(1, 0.3),
      sp: rand(9, 2), ph: rand(TAU),
    }));
    this.embers = Array.from({ length: 26 }, () => ({
      x: rand(this.w), y: rand(820, -200), sp: rand(26, 6), ph: rand(TAU), r: rand(2.2, 0.7),
    }));
    this.buildStatic();
  }

  buildStatic() {
    const s = 0.72;
    const top = WALL_TOP - 60;
    const height = 920 - top;
    this.bgScale = s;
    this.bgTop = top;
    const cv = document.createElement('canvas');
    cv.width = Math.ceil(this.w * s);
    cv.height = Math.ceil(height * s);
    const c = cv.getContext('2d');
    c.scale(s, s);
    c.translate(0, -top);
    this.drawBackWall(c, top, 920);
    this.static = cv;
  }

  drawBackWall(c, top, bottom) {
    const g = c.createLinearGradient(0, top, 0, bottom);
    g.addColorStop(0, '#08090a');
    g.addColorStop(0.18, '#111213');
    g.addColorStop(0.62, '#181817');
    g.addColorStop(0.88, '#201d1a');
    g.addColorStop(1, '#151412');
    c.fillStyle = g;
    c.fillRect(0, top, this.w, bottom - top);

    // distant arches / alcoves
    for (let i = 0; i < 7; i++) {
      const x = 140 + i * 610 + (i % 2) * 80;
      c.fillStyle = '#0b0c0d';
      c.beginPath();
      c.moveTo(x, 700);
      c.lineTo(x, 360);
      c.quadraticCurveTo(x + 90, 270, x + 180, 360);
      c.lineTo(x + 180, 700);
      c.closePath(); c.fill();
      c.strokeStyle = 'rgba(90,86,78,.13)'; c.lineWidth = 5; c.stroke();
      // dim red emergency lamp inside
      const eg = c.createRadialGradient(x + 90, 380, 1, x + 90, 380, 110);
      eg.addColorStop(0, 'rgba(150,26,20,.17)');
      eg.addColorStop(1, 'rgba(150,26,20,0)');
      c.fillStyle = eg;
      c.fillRect(x, 280, 180, 300);
    }

    // concrete panels
    for (let x = 0; x < this.w; x += 236) {
      const shade = 0.9 + noise1(x * 0.11) * 0.24;
      c.fillStyle = `rgba(${34 * shade | 0},${33 * shade | 0},${31 * shade | 0},.45)`;
      c.fillRect(x, -120, 234, 820);
      c.strokeStyle = 'rgba(0,0,0,.34)'; c.lineWidth = 2;
      c.beginPath(); c.moveTo(x, -120); c.lineTo(x, 700); c.stroke();
      c.strokeStyle = 'rgba(120,114,102,.05)'; c.lineWidth = 1;
      c.beginPath(); c.moveTo(x + 2, -120); c.lineTo(x + 2, 700); c.stroke();
      // panel seams horizontal
      for (let y = 40; y < 700; y += 190) {
        c.strokeStyle = 'rgba(0,0,0,.28)'; c.beginPath(); c.moveTo(x, y); c.lineTo(x + 234, y); c.stroke();
      }
      // stains running down
      const n = 1 + (noise1(x * 0.9) * 3 | 0);
      for (let i = 0; i < n; i++) {
        const sx = x + 20 + noise1(x + i * 17) * 190;
        const sy = 130 + noise1(x + i * 5) * 420;
        const len = 60 + noise1(x + i) * 260;
        const grad = c.createLinearGradient(0, sy, 0, sy + len);
        grad.addColorStop(0, 'rgba(6,5,4,.30)');
        grad.addColorStop(1, 'rgba(6,5,4,0)');
        c.fillStyle = grad;
        c.fillRect(sx, sy, 5 + noise1(sx) * 13, len);
      }
    }

    // big structural girders
    for (let x = 420; x < this.w; x += 706) {
      c.fillStyle = '#0c0d0e';
      c.fillRect(x, top, 46, bottom - top);
      c.fillStyle = '#1d1f20';
      c.fillRect(x + 5, top, 8, bottom - top);
      c.fillStyle = 'rgba(160,150,132,.07)';
      c.fillRect(x + 42, top, 3, bottom - top);
      for (let y = -80; y < 700; y += 96) {
        c.fillStyle = '#2a2c2c';
        c.beginPath(); c.arc(x + 16, y, 3.4, 0, TAU); c.fill();
        c.beginPath(); c.arc(x + 30, y, 3.4, 0, TAU); c.fill();
      }
      // diagonal brace
      c.strokeStyle = 'rgba(20,21,22,.9)'; c.lineWidth = 12;
      c.beginPath(); c.moveTo(x + 46, 70); c.lineTo(x + 170, -50); c.stroke();
      c.strokeStyle = 'rgba(110,104,92,.08)'; c.lineWidth = 2;
      c.beginPath(); c.moveTo(x + 46, 70); c.lineTo(x + 170, -50); c.stroke();
    }

    // ceiling truss
    c.fillStyle = '#0a0b0c';
    c.fillRect(0, top, this.w, 84);
    c.strokeStyle = 'rgba(100,94,84,.09)'; c.lineWidth = 3;
    for (let x = 0; x < this.w; x += 236) {
      c.beginPath(); c.moveTo(x, top + 20); c.lineTo(x + 118, top + 66); c.lineTo(x + 236, top + 20); c.stroke();
    }
    c.strokeStyle = 'rgba(90,84,74,.06)'; c.lineWidth = 2;
    for (let x = 120; x < this.w; x += 520) {
      c.beginPath(); c.moveTo(x, top + 84); c.lineTo(x, 140); c.stroke();
    }

    // pipes along wall
    this.pipe(c, 0, 42, 930, 14, '#2a2724', '#0e0d0c');
    this.pipe(c, 0, 90, 2360, 9, '#332a24', '#0f0d0c');
    this.pipe(c, 0, 590, 150, 10, '#232527', '#0b0c0d');
    // pipe joints
    for (let x = 90; x < 2400; x += 340) {
      c.fillStyle = '#3b3833'; c.fillRect(x, 78, 14, 22);
      c.fillStyle = 'rgba(255,255,255,.07)'; c.fillRect(x + 2, 80, 3, 18);
    }
    // valves
    for (let x = 260; x < 2300; x += 690) {
      c.strokeStyle = '#4a4038'; c.lineWidth = 4;
      c.beginPath(); c.arc(x, 94, 15, 0, TAU); c.stroke();
      c.beginPath(); c.moveTo(x - 20, 94); c.lineTo(x + 20, 94); c.stroke();
      c.beginPath(); c.moveTo(x, 74); c.lineTo(x, 114); c.stroke();
    }

    // vents
    for (let i = 0; i < 4; i++) {
      const x = 300 + i * 980, y = 190 + (i % 2) * 40;
      c.fillStyle = '#191a1a'; c.fillRect(x, y, 90, 60);
      c.strokeStyle = '#0a0b0b'; c.lineWidth = 2; c.strokeRect(x, y, 90, 60);
      c.strokeStyle = 'rgba(120,114,102,.16)'; c.lineWidth = 2;
      for (let k = 0; k < 6; k++) { c.beginPath(); c.moveTo(x + 8, y + 8 + k * 8); c.lineTo(x + 82, y + 8 + k * 8); c.stroke(); }
    }

    // warning stripes at wall base
    this.stripes(c, 0, 660, this.w, 38);
    c.fillStyle = 'rgba(8,8,8,.7)';
    c.fillRect(0, 698, this.w, 6);

    // graffiti
    this.graffiti(c, 860, 520, 'NO CLEAN-UP', 'rgba(170,160,140,.16)', 34);
    this.graffiti(c, 1760, 470, 'MEAT', 'rgba(150,22,26,.33)', 74);
    this.graffiti(c, 2860, 545, 'RUN', 'rgba(170,160,140,.14)', 42);
    this.graffiti(c, 3520, 500, 'GOD IS DEAD', 'rgba(150,22,26,.2)', 27);
    // tally marks
    c.strokeStyle = 'rgba(185,175,155,.17)'; c.lineWidth = 3;
    for (let i = 0; i < 17; i++) {
      const x = 1220 + i * 11, y = 470;
      c.beginPath(); c.moveTo(x, y); c.lineTo(x + 2, y + 26); c.stroke();
    }

    // hanging chains and hooks
    for (let i = 0; i < 9; i++) {
      const x = 380 + i * 430 + noise1(i) * 60;
      this.chain(c, x, top + 70, 230 + noise1(i * 2) * 220);
    }

    // floor
    const fg = c.createLinearGradient(0, 690, 0, 920);
    fg.addColorStop(0, '#28251f');
    fg.addColorStop(0.18, '#1b1916');
    fg.addColorStop(1, '#0b0a09');
    c.fillStyle = fg;
    c.fillRect(0, 690, this.w, 230);
    // floor slabs
    c.strokeStyle = 'rgba(0,0,0,.4)'; c.lineWidth = 2;
    for (let x = 0; x < this.w; x += 300) {
      c.beginPath(); c.moveTo(x, 700); c.lineTo(x + 26, 920); c.stroke();
    }
    for (let y = 720; y < 920; y += 48) {
      c.strokeStyle = 'rgba(0,0,0,.18)';
      c.beginPath(); c.moveTo(0, y); c.lineTo(this.w, y); c.stroke();
    }
    // drains
    for (let i = 0; i < 5; i++) {
      const x = 300 + i * 900;
      c.fillStyle = '#0c0c0b';
      c.beginPath(); c.ellipse(x, 806, 44, 12, 0, 0, TAU); c.fill();
      c.strokeStyle = 'rgba(120,114,102,.16)'; c.lineWidth = 2;
      for (let k = -3; k <= 3; k++) { c.beginPath(); c.moveTo(x + k * 10, 797); c.lineTo(x + k * 12, 815); c.stroke(); }
    }
    // puddles
    for (let i = 0; i < 14; i++) {
      const x = rand(this.w), y = rand(790, 720);
      const w = rand(150, 40);
      const pg = c.createRadialGradient(x, y, 1, x, y, w);
      pg.addColorStop(0, 'rgba(90,80,64,.18)');
      pg.addColorStop(0.6, 'rgba(50,48,40,.12)');
      pg.addColorStop(1, 'rgba(0,0,0,0)');
      c.fillStyle = pg;
      c.beginPath(); c.ellipse(x, y, w, w * 0.2, 0, 0, TAU); c.fill();
      c.strokeStyle = 'rgba(190,175,145,.05)'; c.lineWidth = 1;
      c.beginPath(); c.ellipse(x, y - 1, w * 0.8, w * 0.14, 0, 0, TAU); c.stroke();
    }

    // old blood stains baked into the room
    for (let i = 0; i < 22; i++) {
      const x = rand(this.w), y = rand(710, 694);
      c.fillStyle = `rgba(${60 + rand(30) | 0},6,10,${rand(0.35, 0.12)})`;
      c.beginPath();
      c.ellipse(x, y, rand(52, 8), rand(14, 3), rand(0.4, -0.4), 0, TAU);
      c.fill();
    }

    // debris
    for (let i = 0; i < 120; i++) {
      const x = rand(this.w), y = rand(905, 700);
      c.fillStyle = `rgba(${60 + rand(50) | 0},${55 + rand(40) | 0},${45 + rand(30) | 0},${rand(0.35, 0.1)})`;
      c.fillRect(x, y, rand(6, 1), rand(2, 1));
    }

    // vignette-ish wall grime
    const vg = c.createLinearGradient(0, 200, 0, 690);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(0,0,0,.3)');
    c.fillStyle = vg;
    c.fillRect(0, 200, this.w, 500);
  }

  pipe(c, x, y, len, r, col, dark) {
    c.strokeStyle = dark; c.lineWidth = r * 2 + 4; c.lineCap = 'round';
    c.beginPath(); c.moveTo(x, y); c.lineTo(x + len, y); c.stroke();
    c.strokeStyle = col; c.lineWidth = r * 2;
    c.beginPath(); c.moveTo(x, y); c.lineTo(x + len, y); c.stroke();
    c.strokeStyle = 'rgba(255,255,255,.06)'; c.lineWidth = r * 0.5;
    c.beginPath(); c.moveTo(x, y - r * 0.5); c.lineTo(x + len, y - r * 0.5); c.stroke();
  }

  chain(c, x, y, len) {
    c.strokeStyle = 'rgba(80,76,68,.42)'; c.lineWidth = 3;
    for (let yy = y; yy < y + len; yy += 12) {
      c.beginPath(); c.ellipse(x + Math.sin(yy * 0.5) * 1.5, yy, 3.2, 8, 0, 0, TAU); c.stroke();
    }
    // hook
    c.strokeStyle = 'rgba(100,96,88,.5)'; c.lineWidth = 4;
    c.beginPath();
    c.moveTo(x, y + len);
    c.quadraticCurveTo(x + 2, y + len + 26, x + 18, y + len + 20);
    c.stroke();
  }

  stripes(c, x, y, w, h) {
    c.save();
    c.beginPath(); c.rect(x, y, w, h); c.clip();
    c.fillStyle = '#181612'; c.fillRect(x, y, w, h);
    for (let i = -h; i < w; i += 60) {
      c.fillStyle = 'rgba(150,116,30,.5)';
      c.beginPath();
      c.moveTo(x + i, y + h); c.lineTo(x + i + 30, y);
      c.lineTo(x + i + 62, y); c.lineTo(x + i + 32, y + h);
      c.closePath(); c.fill();
    }
    c.fillStyle = 'rgba(0,0,0,.4)'; c.fillRect(x, y, w, 4);
    c.restore();
  }

  graffiti(c, x, y, text, color, size) {
    c.save();
    c.globalAlpha = 0.9;
    c.fillStyle = color;
    c.font = `900 ${size}px "Arial Narrow", Impact, sans-serif`;
    c.letterSpacing = '2px';
    c.translate(x, y);
    c.rotate(-0.03);
    c.fillText(text, 0, 0);
    // drips
    c.fillStyle = color;
    for (let i = 0; i < 4; i++) {
      c.fillRect(10 + i * size * 0.6, 4, 2, size * rand(0.6, 0.15));
    }
    c.restore();
  }

  drawLamps(ctx, time, camX) {
    for (const l of this.lamps) {
      const fl = 1 - Math.abs(Math.sin(time * (3.1 + l.flicker) + l.x)) * 0.06 * l.flicker;
      const x = l.x, y = l.y;
      // cable
      ctx.strokeStyle = 'rgba(20,20,20,.8)'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(x, y - 260); ctx.lineTo(x + 4, y - 22); ctx.stroke();
      // shade
      ctx.fillStyle = '#1c1d1c';
      ctx.beginPath();
      ctx.moveTo(x - 26, y); ctx.lineTo(x + 26, y); ctx.lineTo(x + 15, y - 22); ctx.lineTo(x - 15, y - 22);
      ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(160,140,100,.15)'; ctx.lineWidth = 1.5; ctx.stroke();
      // bulb glow
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const bg = ctx.createRadialGradient(x, y + 6, 1, x, y + 6, 34);
      bg.addColorStop(0, `rgba(255,225,160,${0.55 * fl})`);
      bg.addColorStop(0.4, `rgba(255,170,70,${0.18 * fl})`);
      bg.addColorStop(1, 'rgba(255,140,30,0)');
      ctx.fillStyle = bg;
      ctx.beginPath(); ctx.arc(x, y + 6, 34, 0, TAU); ctx.fill();
      // cone of light
      const cg = ctx.createLinearGradient(0, y, 0, this.ground + 100);
      cg.addColorStop(0, `rgba(255,190,100,${0.13 * fl})`);
      cg.addColorStop(0.5, `rgba(255,170,80,${0.055 * fl})`);
      cg.addColorStop(1, 'rgba(255,150,60,0)');
      ctx.fillStyle = cg;
      ctx.beginPath();
      ctx.moveTo(x - 16, y);
      ctx.lineTo(x + 16, y);
      ctx.lineTo(x + 190, this.ground + 120);
      ctx.lineTo(x - 190, this.ground + 120);
      ctx.closePath(); ctx.fill();
      // local floor pool of light
      const fg = ctx.createRadialGradient(x, this.ground + 10, 4, x, this.ground + 10, 230);
      fg.addColorStop(0, `rgba(255,180,90,${0.15 * fl})`);
      fg.addColorStop(1, 'rgba(255,150,50,0)');
      ctx.fillStyle = fg;
      ctx.beginPath(); ctx.ellipse(x, this.ground + 10, 230, 46, 0, 0, TAU); ctx.fill();
      ctx.restore();
    }
  }

  draw(ctx, time, camX) {
    // static backdrop
    ctx.drawImage(this.static, 0, this.bgTop, this.w, this.static.height / this.bgScale);
    // emergency lamps flicker
    const t = time;
    this.lamps.forEach((l, i) => {
      if (Math.sin(t * (0.7 + l.flicker) + i * 4) > 0.985) {
        ctx.fillStyle = 'rgba(10,8,7,.35)';
        ctx.fillRect(l.x - 260, -120, 520, 820);
      }
    });
    this.drawLamps(ctx, t, camX);
    this.drawDust(ctx, t, camX);
    this.drawBackgroundProps(ctx, t);
  }

  drawDust(ctx, time, camX) {
    ctx.save();
    for (const d of this.dust) {
      const x = ((d.x + Math.sin(time * 0.3 + d.ph) * 36 + time * d.sp) % this.w + this.w) % this.w;
      const y = d.y + Math.sin(time * 0.6 + d.ph) * 14;
      if (Math.abs(x - camX) > 1200) continue;
      const a = 0.06 + (d.z * 0.12);
      ctx.fillStyle = `rgba(230,210,180,${a})`;
      ctx.beginPath(); ctx.arc(x, y, d.z * 1.5, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  drawBackgroundProps(ctx, time) {
    // crates and barrels in the back, behind the action
    const props = [
      [180, 1], [520, 0], [1080, 1], [1250, 0], [1900, 1], [2150, 0], [2650, 1], [3200, 0], [3450, 1], [3920, 0],
    ];
    for (const [x, type] of props) {
      if (type === 1) {
        // crate stack
        this.crate(ctx, x, 630, 84, 70);
        if (x % 2) this.crate(ctx, x + 14, 570, 64, 58);
      } else {
        // barrel
        this.barrel(ctx, x, 640, 34, 62, '#3a3630');
      }
    }
    // hanging meat hooks with old carcasses
    for (let i = 0; i < 3; i++) {
      const x = 1500 + i * 1150;
      ctx.strokeStyle = 'rgba(30,26,24,.9)'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(x, 160); ctx.lineTo(x, 300); ctx.stroke();
      ctx.fillStyle = '#3a211c';
      ctx.beginPath();
      ctx.ellipse(x, 350, 22, 56, 0.05, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(90,20,18,.4)';
      ctx.beginPath(); ctx.ellipse(x + 6, 370, 8, 30, 0.1, 0, TAU); ctx.fill();
      ctx.fillStyle = '#161312';
      ctx.beginPath(); ctx.arc(x, 292, 12, 0, TAU); ctx.fill();
    }
  }

  crate(ctx, x, y, w, h) {
    ctx.save();
    ctx.fillStyle = '#2a231b';
    ctx.fillRect(x - w / 2, y - h, w, h);
    ctx.strokeStyle = 'rgba(0,0,0,.5)'; ctx.lineWidth = 3;
    ctx.strokeRect(x - w / 2, y - h, w, h);
    ctx.strokeStyle = 'rgba(140,115,80,.12)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x - w / 2 + 6, y - h + 6); ctx.lineTo(x + w / 2 - 6, y - 6); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x + w / 2 - 6, y - h + 6); ctx.lineTo(x - w / 2 + 6, y - 6); ctx.stroke();
    ctx.strokeStyle = 'rgba(0,0,0,.3)'; ctx.lineWidth = 1;
    for (let i = 1; i < 4; i++) { ctx.beginPath(); ctx.moveTo(x - w / 2, y - h + i * h / 4); ctx.lineTo(x + w / 2, y - h + i * h / 4); ctx.stroke(); }
    ctx.restore();
  }

  barrel(ctx, x, y, w, h, color) {
    ctx.save();
    const g = ctx.createLinearGradient(x - w, 0, x + w, 0);
    g.addColorStop(0, '#19170f');
    g.addColorStop(0.35, color);
    g.addColorStop(0.62, '#4e4838');
    g.addColorStop(1, '#171510');
    ctx.fillStyle = g;
    ctx.fillRect(x - w / 2, y - h, w, h);
    ctx.strokeStyle = 'rgba(0,0,0,.5)'; ctx.lineWidth = 2; ctx.strokeRect(x - w / 2, y - h, w, h);
    ctx.strokeStyle = 'rgba(180,170,150,.1)'; ctx.lineWidth = 2;
    for (let i = 1; i < 3; i++) { ctx.beginPath(); ctx.moveTo(x - w / 2, y - h + i * h / 3); ctx.lineTo(x + w / 2, y - h + i * h / 3); ctx.stroke(); }
    ctx.restore();
  }

  drawForeground(ctx, time) {
    // floating embers / sparks
    for (const e of this.embers) {
      const x = (e.x + Math.sin(time * 0.5 + e.ph) * 26) % this.w;
      const y = e.y - ((time * e.sp) % 900);
      const yy = y < -300 ? y + 1200 : y;
      ctx.fillStyle = `rgba(255,150,60,${0.08 + Math.abs(Math.sin(time + e.ph)) * 0.18})`;
      ctx.beginPath(); ctx.arc(x, yy, e.r, 0, TAU); ctx.fill();
    }
  }
}

import { rand, TAU, clamp, pick } from './util.js';

const BLOOD = ['rgba(112,5,12,', 'rgba(140,9,16,', 'rgba(88,3,9,'];
const DEV = ['rgba(255,60,40,', 'rgba(200,20,20,'];

export class ScreenFX {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.splats = [];
    this.flash = 0;
    this.flashColor = '255,235,200';
    this.low = 0;
    this.w = 1; this.h = 1; this.dpr = 1;
  }

  resize(w, h, dpr) {
    this.w = w; this.h = h; this.dpr = dpr;
    this.canvas.width = Math.floor(w * dpr);
    this.canvas.height = Math.floor(h * dpr);
  }

  splatter(amount = 1, fromTop = false) {
    const n = Math.floor(2 + amount * 3);
    for (let i = 0; i < n; i++) {
      if (this.splats.length > 42) this.splats.shift();
      const edge = Math.random();
      let x, y;
      if (fromTop) { x = rand(this.w * 0.9, this.w * 0.1); y = rand(this.h * 0.1, 0); }
      else if (edge < 0.5) { x = Math.random() < 0.5 ? rand(this.w * 0.24) : rand(this.w, this.w * 0.76); y = rand(this.h * 0.9, this.h * 0.06); }
      else { x = rand(this.w * 0.88, this.w * 0.1); y = Math.random() < 0.5 ? rand(this.h * 0.18) : rand(this.h, this.h * 0.8); }
      this.splats.push({
        x, y, r: rand(26, 6) * (0.6 + amount * 0.4),
        vx: rand(18, -18), vy: rand(60, 10),
        life: rand(7, 3), max: 7,
        color: pick(BLOOD), stretch: rand(2.2, 0.8),
        drops: Array.from({ length: 3 + (Math.random() * 5 | 0) }, () => ({
          ox: rand(26, -26), oy: rand(20, -20), r: rand(3.4, 0.8),
        })),
      });
    }
  }

  flash(strength = 0.5, color = '255,235,200') {
    this.flash = Math.max(this.flash, strength);
    this.flashColor = color;
  }

  update(dt, hpFrac = 1) {
    this.flash = Math.max(0, this.flash - dt * 3.2);
    this.low = clamp(1 - hpFrac, 0, 1);
    for (let i = this.splats.length - 1; i >= 0; i--) {
      const s = this.splats[i];
      s.life -= dt;
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      s.vy *= 0.995;
      if (s.life <= 0) this.splats.splice(i, 1);
    }
  }

  draw() {
    const c = this.ctx, w = this.w, h = this.h;
    c.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    c.clearRect(0, 0, w, h);
    if (this.low > 0.35) {
      const g = c.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.28, w / 2, h / 2, Math.max(w, h) * 0.72);
      g.addColorStop(0, 'rgba(90,0,4,0)');
      g.addColorStop(1, `rgba(100,2,8,${(this.low - 0.35) * 0.55})`);
      c.fillStyle = g;
      c.fillRect(0, 0, w, h);
    }
    for (const s of this.splats) {
      const a = clamp(s.life / s.max, 0, 1) * 0.75;
      c.save();
      c.translate(s.x, s.y);
      const g = c.createRadialGradient(0, 0, s.r * 0.1, 0, 0, s.r * s.stretch);
      g.addColorStop(0, s.color + (a * 0.9).toFixed(3) + ')');
      g.addColorStop(0.55, s.color + (a * 0.65).toFixed(3) + ')');
      g.addColorStop(1, s.color + '0)');
      c.fillStyle = g;
      c.beginPath(); c.ellipse(0, 0, s.r * s.stretch, s.r, 0, 0, TAU); c.fill();
      for (const d of s.drops) {
        c.fillStyle = s.color + (a * 0.8).toFixed(3) + ')';
        c.beginPath(); c.ellipse(d.ox, d.oy, d.r, d.r * 0.7, 0, 0, TAU); c.fill();
      }
      // drip
      if (s.r > 12) {
        c.strokeStyle = s.color + (a * 0.5).toFixed(3) + ')';
        c.lineWidth = 1.8;
        c.beginPath(); c.moveTo(0, s.r * 0.4); c.lineTo(2, s.r * 0.4 + s.life * 5); c.stroke();
      }
      c.restore();
    }
    if (this.flash > 0.001) {
      c.fillStyle = `rgba(${this.flashColor},${this.flash * 0.55})`;
      c.fillRect(0, 0, w, h);
    }
  }
}

import { WEAPONS } from './weapons.js';
import { clamp } from './util.js';

export class HUD {
  constructor() {
    const $ = id => document.getElementById(id);
    this.root = $('hud');
    this.hpNum = $('hpNum');
    this.hpFill = $('healthFill');
    this.hpGhost = $('healthGhost');
    this.healthBar = $('healthBar');
    this.ammoMag = $('ammoMag');
    this.ammoReserve = $('ammoReserve');
    this.weaponName = $('weaponName');
    this.weaponType = $('weaponType');
    this.weaponBar = $('weaponBar');
    this.crosshair = $('crosshair');
    this.hitmarkerEl = $('hitmarker');
    this.killFeedEl = $('killFeed');
    this.reloadRing = $('reloadRing');
    this.reloadArc = $('reloadArc');
    this.waveNum = $('waveNum');
    this.modeLabel = $('modeLabel');
    this.enemyCount = $('enemyCount');
    this.killNum = $('killNum');
    this.statusTxt = $('statusTxt');
    this.slowmoDot = $('slowmoDot');
    this.crossParts = [...this.crosshair.querySelectorAll('.ch')];
    this.weaponSlots = [];
    this.bannerEl = document.createElement('div');
    this.bannerEl.className = 'wave-banner';
    this.root.appendChild(this.bannerEl);
    this.buildWeaponBar();
    this.lastAmmo = '';
    this.hitTimer = 0;
  }

  buildWeaponBar() {
    this.weaponBar.innerHTML = '';
    for (const d of WEAPONS) {
      const el = document.createElement('div');
      el.className = 'wslot';
      el.innerHTML = `<b>${d.slot}</b>${d.name.slice(0, 4)}`;
      el.title = d.name;
      this.weaponBar.appendChild(el);
      this.weaponSlots.push(el);
    }
  }

  show(v) {
    this.root.classList.toggle('hidden', !v);
  }

  setMode(mode) {
    this.modeLabel.textContent = mode === 'sandbox' ? 'FREE PLAY' : 'SURVIVAL';
  }

  banner(text, sub = '', cls = '') {
    this.bannerEl.className = 'wave-banner ' + cls;
    this.bannerEl.innerHTML = `<div class="wb-text">${text}</div><div class="wb-sub">${sub}</div>`;
    void this.bannerEl.offsetWidth;
    this.bannerEl.classList.add('show');
    clearTimeout(this._bt);
    this._bt = setTimeout(() => this.bannerEl.classList.remove('show'), 2600);
  }

  killFeed(text, crit = false) {
    const el = document.createElement('div');
    el.className = 'kf' + (crit ? ' crit' : '');
    el.innerHTML = text;
    this.killFeedEl.prepend(el);
    while (this.killFeedEl.children.length > 5) this.killFeedEl.lastChild.remove();
    setTimeout(() => el.remove(), 5200);
  }

  hitmarker(kill = false) {
    this.hitmarkerEl.classList.remove('show', 'kill');
    void this.hitmarkerEl.offsetWidth;
    if (kill) this.hitmarkerEl.classList.add('kill');
    this.hitmarkerEl.classList.add('show');
  }

  flashDamage() {
    const el = document.getElementById('damageFlash');
    el.classList.add('on');
    clearTimeout(this._dt);
    this._dt = setTimeout(() => el.classList.remove('on'), 180);
  }

  update(g) {
    const p = g.player;
    if (!p) return;
    const hpFrac = clamp(p.hp / p.maxHp, 0, 1);
    const hp = Math.max(0, Math.ceil(p.hp));
    this.hpNum.textContent = hp;
    this.hpFill.style.width = (hpFrac * 100) + '%';
    this.hpGhost.style.width = (hpFrac * 100) + '%';
    this.healthBar.classList.toggle('low', hpFrac < 0.3);
    this.statusTxt.textContent = hpFrac > 0.65 ? 'STABLE' : hpFrac > 0.3 ? 'BLEEDING' : 'CRITICAL';
    this.slowmoDot.classList.toggle('hidden', !g.slowmo);

    const d = g.arsenal.def, s = g.arsenal.state;
    this.weaponName.textContent = d.name;
    this.weaponType.textContent = d.sub;
    this.ammoMag.textContent = d.kind === 'gun' ? s.mag : d.kind === 'throw' ? s.reserve : '∞';
    this.ammoReserve.textContent = d.kind === 'gun' ? s.reserve : d.kind === 'throw' ? 'THROWABLES' : d.kind === 'melee' || d.kind === 'saw' ? '' : '';
    if (d.kind === 'gun' || d.kind === 'throw') {
      this.ammoReserve.textContent = d.kind === 'gun' ? s.reserve : 'FRAG';
    }
    this.ammoMag.classList.toggle('empty', d.kind === 'gun' && s.mag === 0);
    const ammoKey = `${d.id}:${s.mag}:${s.reserve}`;
    if (ammoKey !== this.lastAmmo) {
      this.lastAmmo = ammoKey;
      this.ammoMag.animate?.([
        { transform: 'translateY(0)' }, { transform: 'translateY(-4px)' }, { transform: 'translateY(0)' },
      ], { duration: 120, easing: 'ease-out' });
    }

    const spread = g.arsenal.currentSpread(g.input.aim);
    const gap = 7 + spread * 520 + clamp(Math.abs(p.vx) / 26, 0, 10);
    this.crossParts[0].style.transform = `translateY(${-gap}px)`;
    this.crossParts[1].style.transform = `translateY(${gap}px)`;
    this.crossParts[2].style.transform = `translateX(${-gap}px)`;
    this.crossParts[3].style.transform = `translateX(${gap}px)`;
    this.crosshair.classList.toggle('melee', d.kind === 'melee' || d.kind === 'saw');
    this.crosshair.style.opacity = g.state === 'menu' ? 0 : 1;

    const reloading = s.reloading > 0;
    this.reloadRing.classList.toggle('show', reloading);
    if (reloading) {
      const pct = g.arsenal.reloadProgress();
      this.reloadArc.style.strokeDashoffset = String(94.2 * (1 - pct));
    }

    this.waveNum.textContent = g.mode === 'sandbox' ? '∞' : String(g.wave).padStart(2, '0');
    this.enemyCount.textContent = g.aliveEnemyCount();
    this.killNum.textContent = g.kills;

    for (let i = 0; i < this.weaponSlots.length; i++) {
      this.weaponSlots[i].classList.toggle('active', i === g.arsenal.index);
    }
  }
}

