 base clamp x 0..worldW-viewW
 camX = lerp(camX,targetX,1-exp(-dt*5)) for player; menu slower.
 shake decay; shake amp from this.camera.shake.
 camera.x = camX + shakeX; camera.y = camY + shakeY.
}
