297:     window.addEventListener('keydown', e => {
298:       const k = e.key.toLowerCase();
299:       if (['tab', ' ', 'arrowup', 'arrowdown'].includes(k)) e.preventDefault();
300:       if (this.input.keys.has(k) && k !== 'escape') return;
301:       this.input.keys.add(k);
302:       this.audio.init();
303:       if (k === 'escape') {
304:         if (this.panelOpen) this.closePanel();
305:         else if (this.state === 'playing' && this.deathTimer <= 0) this.togglePause();
306:       } else if (k === 'tab') {
307:         if (this.state === 'playing') this.togglePanel();
308:       } else if (this.state === 'playing' && this.deathTimer <= 0) {
309:         if (/^[1-8]$/.test(k)) this.selectWeapon(Number(k) - 1);
310:         else if (k === 'q') this.swapWeapon(1);
311:         else if (k === 'r') this.reload();
312:         else if (k === 't') this.toggleSlowmo();
313:         else if (k === 'g') this.throwGrenade(false);
314:         else if (k === 'w' || k === 'arrowup') this.jump();
315:         else if (k === ' ') this.roll();
316:         else if (k === 'm') { this.audio.setMuted(!this.audio.muted); }
317:         else if (this.mode === 'sandbox') this.sandboxKey(k);
318:       }
319:     });
320:     window.addEventListener('keyup', e => this.input.keys.delete(e.key.toLowerCase()));
321:     window.addEventListener('blur', () => {
322:       this.input.keys.clear();
323:       this.input.attackHeld = false; this.input.aim = false;
324:       if (this.state === 'playing' && !this.panelOpen && this.deathTimer <= 0 && !this.paused) this.togglePause();
325:     });
