374:   sandboxKey(k) {
375:     if (k === 'j') this.sandboxAction('dummy');
376:     else if (k === 'k') this.sandboxAction('hostile');
377:     else if (k === 'h') this.sandboxAction('heal');
378:     else if (k === 'u') this.sandboxAction('ammo');
379:     else if (k === 'c') this.sandboxAction('clear');
380:     else if (k === 'b') this.sandboxAction('rain');
