383:   sandboxAction(action) {
384:     if (!this.player || !this.player.alive) return;
385:     this.audio.init();
386:     const p = this.player;
387:     if (action === 'dummy') {
388:       this.spawnDummy(clampX(p.x + (chance(0.5) ? 1 : -1) * rand(320, 140)));
389:       this.hud.killFeed('SUBJECT <b>DEPLOYED</b>', false);
390:     } else if (action === 'hostile') {
391:       this.spawnEnemy(pick(['thug', 'gunner', 'brute']), clampX(p.x + (chance(0.5) ? 1 : -1) * rand(300, 120)));
392:       this.hud.killFeed('HOSTILE <b>RELEASED</b>', true);
393:     } else if (action === 'heal') {
394:       p.hp = p.maxHp; p.wounds.length = 0;
395:       this.hud.killFeed('VITALS <b>RESTORED</b>', false);
396:     } else if (action === 'ammo') {
397:       this.arsenal.addAmmo(2);
398:       this.hud.killFeed('AMMUNITION <b>RESTOCKED</b>', false);
399:     } else if (action === 'clear') {
400:       this.actors = this.actors.filter(a => a === this.player || a.alive);
401:       if (this.standActor) this.standActor = null;
402:       this.gore.clear();
403:       this.grenades.length = 0;
404:       this.barrels = this.makeBarrels();
405:       this.hud.killFeed('FLOOR <b>BLEACHED</b>', false);
406:     } else if (action === 'slowmo') {
407:       this.toggleSlowmo();
408:     } else if (action === 'gore') {
409:       const m = this.mouseWorld();
410:       this.explode(m.x, clamp(m.y, -100, GROUND - 10), 260, 300, 'GORE BOMB');
411:     } else if (action === 'rain') {
412:       this.bloodRain = 4.5;
413:       this.hud.banner('BLOOD RAIN', 'LOOK UP', 'danger');
414:     }
415:     this.audio.ui();
416:   }
