418:   // ---------- dimensions & camera ----------
419:   resize() {
420:     const w = Math.max(320, window.innerWidth);
421:     const h = Math.max(320, window.innerHeight);
422:     const dpr = Math.min(2, window.devicePixelRatio || 1);
423:     this.w = w; this.h = h; this.dpr = dpr;
424:     this.canvas.width = Math.floor(w * dpr);
425:     this.canvas.height = Math.floor(h * dpr);
426:     this.fx.resize(w, h, dpr);
427:     const aspect = w / h;
428:     let viewW = 1300;
429:     let viewH = viewW / aspect;
430:     if (viewH < 700) { viewH = 700; viewW = viewH * aspect; }
431:     if (viewH > 1400) { viewH = 1400; viewW = viewH * aspect; }
432:     this.viewW = viewW; this.viewH = viewH;
433:     this.camera.w = viewW; this.camera.h = viewH;
434:     this.camera.scale = w / viewW;
435:     const anchor = viewH > 1150 ? 0.7 : 0.78;
436:     this.groundAnchor = anchor;
437:     this.camY = GROUND_Y - viewH * anchor;
438:     this.camX = clamp(this.camX, 0, WORLD_W - viewW);
439:   }
440: 
441:   screenToWorld(cx, cy) {
442:     const c = this.camera;
443:     return { x: c.x + cx / c.scale, y: c.y + cy / c.scale };
444:   }
445: 
446:   mouseWorld() {
447:     if (this.touchMode && this.input.touchAim && this.input.touchAimT > 0) return this.input.touchAim;
448:     return this.screenToWorld(this.input.mouse.x, this.input.mouse.y);
449:   }
450: 
451:   updateCamera(dt) {
452:     const c = this.camera;
453:     let targetX, targetY;
454:     if (this.state === 'menu') {
455:       targetX = 1050 + Math.sin(this.time * 0.09) * 210 + Math.sin(this.time * 0.023) * 120;
456:       targetY = GROUND_Y - this.viewH * 0.76;
457:       this.camX = targetX;
458:       this.camY = targetY;
459:     } else if (this.player) {
460:       const p = this.player;
461:       const chest = p.alive ? { x: p.x, y: p.y - 110 } : (p.pose?.hip || { x: p.x, y: p.y - 60 });
462:       targetX = chest.x + (p.alive ? clamp(Math.cos(p.aim) * 130, -130, 130) : 0);
463:       targetY = GROUND_Y - this.viewH * this.groundAnchor;
464:       if (!p.alive) {
465:         const hip = p.pose?.hip;
466:         if (hip) targetY = hip.y - this.viewH * 0.46;
467:       }
468:       const follow = this.state === 'dying' || this.state === 'dead' ? 3 : 7;
469:       this.camX = lerp(this.camX, targetX - this.viewW / 2, 1 - Math.exp(-dt * follow));
470:       this.camY = lerp(this.camY, targetY, 1 - Math.exp(-dt * (follow * 0.7)));
471:     }
472:     this.camX = clamp(this.camX, 0, Math.max(0, WORLD_W - this.viewW));
473:     if (this.state !== 'menu') this.camY = clamp(this.camY, -600, 980 - this.viewH);
474: 
475:     c.shake = Math.max(0, c.shake - dt * 38);
476:     const amp = c.shake * 0.6;
477:     c.shakeX = rand(amp, -amp);
478:     c.shakeY = rand(amp, -amp);
479:     c.x = this.camX + c.shakeX;
480:     c.y = this.camY + c.shakeY;
481:   }
482: 
483:   addShake(n) { this.camera.shake = Math.min(30, this.camera.shake + n); }
484: 
485:   addTracer(x1, y1, x2, y2, color = 'pale') {
486:     this.tracers.push({ x1, y1, x2, y2, life: 0.085, max: 0.085, color });
487:   }
488: 
489:   // ---------- main loop ----------
490:   frame = (now) => {
491:     const raw = clamp((now - this.last) / 1000, 0.0001, 0.05);
492:     this.last = now;
493:     this.fpsSamples.push(raw);
494:     if (this.fpsSamples.length > 30) this.fpsSamples.shift();
495:     if (this.state === 'menu') {
496:       const dt = Math.min(raw, 0.033);
497:       this.time += dt;
498:       for (const a of this.actors) a.update(dt);
499:       this.gore.update(dt * 0.85);
500:       this.fx.update(raw, 1);
501:       this.updateCamera(dt);
502:       if (this.standActor) {
503:         this.standActor.aim = Math.PI * 0.82 + Math.sin(this.time * 0.4) * 0.05;
504:       }
505:     } else if (!this.paused) {
506:       let scale = this.slowmo ? 0.34 : 1;
507:       if (this.slowTimer > 0) { scale = Math.min(scale, 0.38); this.slowTimer -= raw; }
508:       if (this.deathTimer > 0) scale = Math.min(scale, 0.5);
509:       if (this.hitstop > 0) { this.hitstop -= raw; scale = Math.min(scale, 0.08); }
510:       const dt = raw * Math.max(0.04, scale);
511:       this.timeScale = scale;
512:       this.time += dt;
513:       this.update(dt, raw);
514:       this.updateCamera(dt);
515:     }
516:     this.render(raw);
517:     this.hud.update(this);
518:     requestAnimationFrame(this.frame);
519:   };
520: 
521:   update(dt, raw) {
522:     const p = this.player;
523:     this.rollCd = Math.max(0, this.rollCd - raw);
524:     this.invuln = Math.max(0, this.invuln - raw);
525:     this.quickThrowCd = Math.max(0, this.quickThrowCd - raw);
526:     this.damageTimer += raw;
527: 
528:     if (p && p.alive) {
529:       this.updatePlayer(p, dt, raw);
530:     } else if (p) {
531:       p.weaponDef = this.arsenal.def;
532:     }
533: 
534:     for (const a of this.actors) {
535:       a.muzzleFlash = Math.max(0, (a.muzzleFlash || 0) - dt * 16);
536:       a.pumpAnim = Math.max(0, (a.pumpAnim || 0) - dt * 4);
537:       if (a !== p) {
538:         if (a.alive && a.type === 'enemy') this.updateEnemy(a, dt, raw);
539:         a.update(dt);
540:       }
541:     }
542:     if (p) p.update(dt);
543: 
544:     for (const b of this.barrels) if (b.burn > 0) { b.burn -= dt; }
545: 
546:     // grenades
547:     for (let i = this.grenades.length - 1; i >= 0; i--) {
548:       const g = this.grenades[i];
549:       g.fuse -= dt;
550:       g.vy += 2000 * dt;
551:       g.x += g.vx * dt; g.y += g.vy * dt;
552:       g.rot += g.vr * dt;
553:       if (g.y > GROUND - 6) {
554:         g.y = GROUND - 6;
555:         if (Math.abs(g.vy) > 60) { g.vy *= -0.42; g.vx *= 0.7; g.vr *= 0.6; this.audio.impact('metal'); }
556:         else { g.vy = 0; g.vx *= 0.82; g.vr *= 0.85; }
557:       }
558:       if (g.x < 60 || g.x > WORLD_W - 60) { g.x = clamp(g.x, 60, WORLD_W - 60); g.vx *= -0.5; }
559:       if (g.fuse <= 0) {
560:         this.grenades.splice(i, 1);
561:         this.explode(g.x, g.y, 200, 170, 'M67');
562:       }
563:     }
564:     // delayed explosions (barrel chains)
565:     for (let i = this.pendingBooms.length - 1; i >= 0; i--) {
566:       const b = this.pendingBooms[i];
567:       b.t -= dt;
568:       if (b.t <= 0) { this.pendingBooms.splice(i, 1); this.explode(b.x, b.y, b.radius, b.damage, b.label || 'BARREL'); }
569:     }
570:     for (let i = this.tracers.length - 1; i >= 0; i--) {
571:       this.tracers[i].life -= dt;
572:       if (this.tracers[i].life <= 0) this.tracers.splice(i, 1);
573:     }
574: 
575:     this.gore.update(dt);
576: 
577:     // player is out of combat -> recover
578:     if (p && p.alive) {
579:       if (this.damageTimer > 6 && p.hp < p.maxHp && p.hp > 0) {
580:         p.hp = Math.min(p.maxHp, p.hp + dt * 7);
581:       }
582:     }
583: 
584:     if (this.bloodRain > 0) {
585:       this.bloodRain -= dt;
586:       for (let i = 0; i < 3; i++) {
587:         this.gore.bloodDrip(rand(this.camX + this.viewW, this.camX), this.camY - 20, 1, 1.2, 40, { size: 2.5 });
588:       }
589:     }
590: 
591:     if (this.mode === 'survive') this.updateWaves(dt);
592:     this.fx.update(raw, p ? clamp(p.hp / p.maxHp, 0, 1) : 1);
593: 
594:     if (this.deathTimer > 0) {
595:       this.deathTimer -= raw;
596:       if (this.deathTimer <= 0) this.showDeathScreen();
597:     }
598:   }
599: 
600:   updatePlayer(p, dt, raw) {
601:     this.arsenal.update(dt);
602:     p.weaponDef = this.arsenal.def;
603:     this.lastWeapon = this.arsenal.def;
604: 
605:     // aim
606:     let aimTarget = null;
607:     if (this.touchMode) {
608:       this.input.touchAimT = Math.max(0, this.input.touchAimT - raw);
609:       if (this.input.touchAim && this.input.touchAimT > 0) {
610:         aimTarget = Math.atan2(this.input.touchAim.y - (p.y - 118), this.input.touchAim.x - p.x);
611:       } else {
612:         const e = this.nearestEnemy();
613:         if (e) {
614:           const pose = e.pose;
615:           aimTarget = Math.atan2((pose ? pose.neck.y : e.y - 120) - (p.y - 118), e.x - p.x);
616:         }
617:       }
618:     }
619:     if (aimTarget === null) {
620:       const m = this.mouseWorld();
621:       if (Math.hypot(m.x - p.x, m.y - (p.y - 118)) > 12) {
622:         aimTarget = Math.atan2(m.y - (p.y - 118), m.x - p.x);
623:       }
624:     }
625:     if (aimTarget !== null) p.aim = angleLerp(p.aim, aimTarget, 1 - Math.exp(-dt * 26));
626: 
627:     const keys = this.input.keys;
628:     let move = (keys.has('d') || keys.has('arrowright') ? 1 : 0) - (keys.has('a') || keys.has('arrowleft') ? 1 : 0);
629:     if (this.touchMode) move = clamp(this.input.touchMove + move * 0.8, -1, 1);
630:     const sprint = keys.has('shift');
631:     const speed = (sprint ? 505 : 330) * (this.invuln > 0 ? 1.35 : 1);
632:     const accel = p.onGround ? 16 : 4.5;
633:     const targetVx = move * speed;
634:     p.vx = lerp(p.vx, targetVx, 1 - Math.exp(-dt * accel));
635: 
636:     p.vy += 2150 * dt;
637:     p.y += p.vy * dt;
638:     p.x += p.vx * dt;
639:     if (p.y >= GROUND) {
640:       if (!p.onGround && p.vy > 300) { this.audio.footstep(); this.gore.dust(p.x, p.y, 2, 5); }
641:       p.y = GROUND; p.vy = 0; p.onGround = true;
642:     } else p.onGround = false;
643:     if (p.x < 55) { p.x = 55; p.vx = Math.max(0, p.vx); }
644:     if (p.x > WORLD_W - 55) { p.x = WORLD_W - 55; p.vx = Math.min(0, p.vx); }
645: 
646:     p.meleeProgress = this.arsenal.meleeProgress();
647:     p.pumpAnim = this.arsenal.state.pump > 0 ? 1 : 0;
648: 
649:     // footsteps
650:     if (Math.abs(p.vx) > 60 && p.onGround) {
651:       this.stepAcc = (this.stepAcc || 0) + raw;
652:       if (this.stepAcc > (sprint ? 0.3 : 0.42)) { this.stepAcc = 0; this.audio.footstep(); if (chance(0.4)) this.gore.dust(p.x, p.y, 1, 3); }
653:     }
654: 
655:     // attacks
656:     const d = this.arsenal.def;
657:     const pressed = this.input.attackPressed;
658:     if (d.kind === 'melee' || d.kind === 'saw') {
659:       if (this.input.attackHeld || pressed) {
660:         const swing = this.arsenal.startMelee();
661:         if (swing) {
662:           this.audio.swing();
663:           p.vx += Math.cos(p.aim) * (d.kind === 'saw' ? 12 : 40);
664:           this.addShake(d.shake * 0.35);
665:         }
666:       }
667:       if (this.arsenal.consumeMeleeHit()) this.resolveMelee();
668:       if (d.kind === 'saw' && this.input.attackHeld && chance(0.6)) {
669:         const pose = p.pose;
670:         const hx = pose.handR.x, hy = pose.handR.y;
671:         this.gore.sprayCone(hx, hy, p.aim, 0.9, 2, 220, 1.8);
672:       }
673:     } else if (d.kind === 'throw') {
674:       if (pressed) this.throwGrenade(false);
675:     } else if (d.kind === 'gun') {
676:       const auto = d.id === 'smg' || d.id === 'rifle';
677:       if (pressed || (auto && this.input.attackHeld)) this.playerShoot();
678:     }
679: 
680:     // reload hint
681:     if (d.kind === 'gun' && this.arsenal.state.mag === 0 && this.arsenal.state.reloading === 0 && this.arsenal.state.reserve > 0 && pressed) {
682:       this.reload();
683:     }
684:     if (pressed) this.input.attackPressed = false;
685:   }
