687:   playerShoot() {
688:     const p = this.player;
689:     if (!p || !p.alive) return;
690:     const a = this.arsenal;
691:     const d = a.def, s = a.state;
692:     if (s.reloading > 0) return;
693:     if (s.mag <= 0) {
694:       this.audio.dryFire();
695:       if (s.reserve > 0) this.reload();
696:       return;
697:     }
698:     const shot = a.shoot(this.input.aim);
699:     if (!shot) return;
700:     const pose = p.pose;
701:     const hand = pose.handR;
702:     const m = {
703:       x: hand.x + Math.cos(p.aim) * (d.muzzle * 0.85),
704:       y: hand.y + Math.sin(p.aim) * (d.muzzle * 0.85),
705:     };
706:     p.recoilKick = 1;
707:     p.muzzleFlash = 1;
708:     this.addShake(d.shake);
709:     this.audio.shot(d.sound, 1);
710:     this.gore.casing(hand.x, hand.y, p.facing * 0.7, p.aim);
711:     this.gore.dust(m.x, m.y, 3, 7, 'rgba(190,190,180,');
712:     this.gore.spark(m.x, m.y, Math.cos(p.aim), Math.sin(p.aim), 3, '#ffd9a0');
713: 
714:     const pellets = shot.pellets || 1;
715:     for (let i = 0; i < pellets; i++) {
716:       const spreadAngle = p.aim + (Math.random() + Math.random() - 1) * shot.spread;
717:       this.resolveBullet(m.x, m.y, spreadAngle, shot, p, 'player');
718:     }
719:     p.vx -= Math.cos(p.aim) * d.recoil * 20;
720:     p.vy -= Math.sin(p.aim) * d.recoil * 8;
721:     // fire penalty to accuracy via recoil, handled in arsenal bloom
722:   }
