724:   resolveBullet(ox, oy, angle, def, owner, tag) {
725:     const dx = Math.cos(angle), dy = Math.sin(angle);
726:     const range = def.range || 1800;
727:     let bestT = range;
728:     let bestHit = null;
729:     let hitBarrel = null;
730: 
731:     for (const a of this.actors) {
732:       if (a === owner) continue;
733:       const hit = a.rayHit(ox, oy, dx, dy, bestT, true);
734:       if (hit && hit.t < bestT) { bestT = hit.t; bestHit = hit; hitBarrel = null; }
735:     }
736:     for (const b of this.barrels) {
737:       if (!b.alive) continue;
738:       const bx = b.x, by = b.y - 34;
739:       const ex = bx - ox, ey = by - oy;
740:       const proj = ex * dx + ey * dy;
741:       if (proj < 0 || proj > bestT) continue;
742:       const px = ox + dx * proj - bx, py = oy + dy * proj - by;
743:       if (px * px + py * py < (b.radius + 3) * (b.radius + 3)) {
744:         bestT = proj; bestHit = null; hitBarrel = b;
745:       }
746:     }
747: 
748:     let endX = ox + dx * bestT, endY = oy + dy * bestT;
749:     if (bestHit) {
750:       const target = bestHit.actor;
751:       const wasAlive = target.alive;
752:       if (target.alive) {
753:         const res = target.takeDamage(def.damage, bestHit.part, bestHit.x, bestHit.y, angle, (def.damage || 20) * 22, {
754:           sever: def.sever || 0, weapon: def.name || 'BULLET', headshot: bestHit.part === 'head',
755:         });
756:         if (target !== this.player) {
757:           this.hud.hitmarker(res.dead);
758:           this.audio.hitmarker(res.dead);
759:         }
760:         if (res.severed) this.gore.bloodBurst(bestHit.x, bestHit.y, 320, 14);
761:         if (res.dead && res.part === 'head' && chance(0.6)) {
762:           this.gore.bloodMist(bestHit.x, bestHit.y, 46);
763:         }
764:         if (target === this.player) this.onPlayerHurt(def.damage, bestHit.x, bestHit.y);
765:         this.gore.sprayCone(bestHit.x, bestHit.y, angle, 0.5, 5, 260, 2.4);
766:       } else {
767:         target.hitCorpse(bestHit.x, bestHit.y, angle, def.damage * 16, def.damage);
768:         if (def.id === 'shotgun') {
769:           const rd = target.ragdoll;
770:           if (rd && chance(0.35)) {
771:             const links = rd.links.filter(l => !l.cut && ['upperArmL', 'upperArmR', 'thighL', 'thighR', 'foreArmL', 'foreArmR'].includes(l.name));
772:             if (links.length) {
773:               const l = pick(links);
774:               rd.cutBone(l.name);
775:               const pt = rd.points[l.b];
776:               if (pt) {
777:                 this.limbs++;
778:                 this.gore.bloodBurst(pt.x, pt.y, 200, 8);
779:                 this.gore.gib(pt.x, pt.y, rand(180, -180), rand(-100, -300), 6, '#8a5a44');
780:               }
781:             }
782:           }
783:         }
784:       }
785:     } else if (hitBarrel) {
786:       this.damageBarrel(hitBarrel, def.damage);
787:     } else {
788:       // background wall / debris impact
789:       this.wallImpact(endX, endY, angle);
790:     }
791: 
792:     this.addTracer(ox, oy, endX, endY, def.tracer || 'pale');
793:     return { x: endX, y: endY, hit: bestHit, barrel: hitBarrel };
794:   }
795: 
796:   wallImpact(x, y, angle) {
797:     this.gore.spark(x, y, -Math.cos(angle), -Math.sin(angle), 5 + (Math.random() * 5 | 0), '#ffcf90');
798:     this.gore.dust(x, y, 2, 5);
799:     this.audio.impact(chance(0.25) ? 'metal' : 'concrete');
800:     const c = this.gore.dctx;
801:     c.save();
802:     c.fillStyle = 'rgba(10,8,7,.55)';
803:     c.beginPath(); c.arc(x, y, rand(3.2, 1.4), 0, TAU); c.fill();
804:     c.strokeStyle = 'rgba(35,30,26,.35)'; c.lineWidth = 1;
805:     for (let i = 0; i < 3; i++) {
806:       const a = rand(TAU);
807:       c.beginPath(); c.moveTo(x, y); c.lineTo(x + Math.cos(a) * rand(12, 4), y + Math.sin(a) * rand(12, 4)); c.stroke();
808:     }
809:     c.restore();
810:   }
