869:   nearestEnemy() {
870:     let best = null, bd = 1e9;
871:     const p = this.player;
872:     for (const a of this.actors) {
873:       if (!a.alive || a === p || a.type === 'dummy') continue;
874:       const d = Math.abs(a.x - p.x);
