880:   resolveMelee() {
881:     const p = this.player;
882:     const d = this.arsenal.def;
883:     const chest = { x: p.x + Math.cos(p.aim) * 18, y: p.y - 108 + Math.sin(p.aim) * 12 };
884:     let hitAny = false;
885:     let hitAlive = false;
886:     let hitPoint = null;
887:     const range = d.range;
888: 
889:     for (const a of this.actors) {
890:       if (a === p) continue;
891:       let best = null;
892:       for (const s of a.hitSegments()) {
893:         if (!a.alive && s.part === 'head' && a.ragdoll?.links.find(x => x.name === 'neck')?.cut) continue;
894:         const q = pointSeg(chest.x, chest.y, s.ax, s.ay, s.bx, s.by);
895:         if (q.dist > range + s.r) continue;
896:         const ang = Math.atan2(q.y - chest.y, q.x - chest.x);
897:         let diff = Math.abs(((ang - p.aim + Math.PI * 3) % TAU) - Math.PI);
898:         if (diff > d.arc / 2) continue;
899:         if (!best || q.dist < best.dist) best = { q, s, part: s.part };
900:       }
901:       if (!best) continue;
902:       hitPoint = best.q;
903:       if (a.alive) {
904:         hitAlive = true;
905:         const dmg = d.damage;
906:         const res = a.takeDamage(dmg, best.part, best.q.x, best.q.y, p.aim, d.knock * (d.kind === 'saw' ? 0.2 : 1), {
907:           sever: d.sever, weapon: d.name, melee: true,
908:         });
909:         const kx = Math.cos(p.aim) * d.knock * 0.05;
910:         a.x = clampX(a.x + kx);
911:         a.stun = d.kind === 'sledge' ? 0.5 : 0.18;
912:         this.audio.flesh(true);
913:         this.hud.hitmarker(res.dead);
914:         this.audio.hitmarker(res.dead);
915:         if (res.severed) this.gore.bloodBurst(best.q.x, best.q.y, 380, 16);
916:         this.gore.sprayCone(best.q.x, best.q.y, p.aim, 0.8, 12, 380, 3.2);
917:       } else {
918:         this.chopCorpse(a, best);
919:       }
920:       hitAny = true;
921:       if (d.kind === 'saw') break;
922:     }
923: 
924:     // barrels
925:     for (const b of this.barrels) {
926:       if (!b.alive) continue;
927:       const q = pointSeg(chest.x, chest.y, b.x - 24, b.y - 60, b.x + 24, b.y - 6);
928:       const ang = Math.atan2(q.y - chest.y, q.x - chest.x);
929:       const diff = Math.abs(((ang - p.aim + Math.PI * 3) % TAU) - Math.PI);
930:       if (q.dist < range + 10 && diff < d.arc / 2) { this.damageBarrel(b, 60); hitAny = true; }
931:     }
932: 
933:     if (hitAny) {
934:       this.addShake(d.shake);
935:       this.hitstop = d.kind === 'sledge' ? 0.055 : 0.025;
936:       if (hitAlive) this.fx.flash(0.08, '255,240,220');
937:       if (hitPoint) {
938:         this.gore.bloodDrip(hitPoint.x, hitPoint.y, 4, 1.2, 220, { size: 3 });
939:       }
940:     } else {
941:       const ex = chest.x + Math.cos(p.aim) * (range + 10);
942:       const ey = chest.y + Math.sin(p.aim) * (range + 10);
943:       this.gore.dust(ex, ey, 2, 4);
944:       if (chance(0.5)) this.gore.spark(ex, ey, -Math.cos(p.aim), -Math.sin(p.aim), 2, '#cfc0a0');
945:     }
946:   }
947: 
948:   chopCorpse(a, best) {
949:     const rd = a.ragdoll;
950:     if (!rd) return;
951:     const links = rd.links.filter(l => !l.cut && ['upperArmL', 'upperArmR', 'thighL', 'thighR', 'foreArmL', 'foreArmR', 'neck'].includes(l.name));
952:     if (links.length && chance(0.72)) {
953:       const l = pick(links);
954:       rd.cutBone(l.name);
955:       a.limbsLost++;
956:       this.limbs++;
957:       const pt = rd.points[l.b];
958:       if (pt) {
959:         this.gore.bloodBurst(pt.x, pt.y, 340, 18);
960:         this.gore.bloodMist(pt.x, pt.y, 36);
961:         for (let i = 0; i < 3; i++) this.gore.gib(pt.x, pt.y, rand(300, -300), rand(-120, -360), rand(8, 3), pick(['#8a5a44', '#7a4030']), { bone: i === 0 });
962:         this.audio.squelch();
963:         if (l.name === 'neck') this.hud.killFeed('<b>DECAPITATED</b> · CORPSE', true);
964:       }
965:     } else {
966:       this.gore.bloodDrip(best.q.x, best.q.y, 6, 1.2, 200, { size: 3 });
967:       if (chance(0.5)) this.gore.gib(best.q.x, best.q.y, rand(180, -180), rand(-80, -260), rand(6, 3), '#8a5a44');
968:     }
969:     const aim = this.player ? this.player.aim : 0;
970:     a.ragdoll?.impulse(best.q.x, best.q.y, Math.cos(aim) * 2, -2, 0.8);
971:   }
