1001:     const a = new Actor({
1002:       x: clampX(sx), type: 'enemy', enemyType: type, gore: this.gore, audio: this.audio,
1003:       worldW: WORLD_W, groundY: GROUND, hp: cfg.hp + (this.mode === 'survive' ? this.wave * 6 : 0),
1004:       weapon: cfg.weapon, aim: p ? Math.atan2((p.y - 118) - (GROUND - 130), p.x - sx) : 0,
1005:       shirt: type === 'brute' ? '#3b3128' : undefined,
1006:     });
1007:     a.onDeath = (act, info) => this.onActorDeath(act, info);
1008:     a.speed = cfg.speed;
1009:     a.attackCd = rand(1.4, 0.4);
1010:     a.swingHit = false;
1011:     a.meleeProgress = -1;
1012:     a.enemyType = type;
1013:     this.actors.push(a);
1014:     if (p) a.aim = Math.atan2((p.y - 118) - (a.y - 130), p.x - a.x);
