1018:   updateEnemy(a, dt, raw) {
1019:     const p = this.player;
1020:     if (!p || !p.alive) {
1021:       a.vx = lerp(a.vx, 0, 1 - Math.exp(-dt * 4));
1022:       a.x += a.vx * dt;
1023:       return;
1024:     }
1025:     const dx = p.x - a.x;
1026:     const adx = Math.abs(dx);
1027:     const dy = (p.y - 118) - (a.y - 130);
1028:     let aim = Math.atan2(dy, dx);
1029:     const inaccuracy = 0.04 + Math.min(0.1, adx / 12000);
1030:     a.aim = angleLerp(a.aim, aim + (chance(0.02) ? rand(inaccuracy, -inaccuracy) : 0), 1 - Math.exp(-dt * 5.5));
1031: 
1032:     let desired, speed;
1033:     if (a.enemyType === 'gunner') { desired = 340; speed = a.speed; }
1034:     else if (a.enemyType === 'brute') { desired = 72; speed = a.speed; }
1035:     else { desired = 58; speed = a.speed; }
1036:     let moveDir = 0;
1037:     if (adx > desired + 45) moveDir = dx > 0 ? 1 : -1;
1038:     else if (adx < desired - 55) moveDir = dx > 0 ? -1 : 1;
1039:     else if (a.enemyType === 'gunner') moveDir = Math.sin(this.time * 0.9 + a.id) * 0.65;
1040: 
1041:     // flanking / separation
1042:     let sep = 0;
1043:     for (const o of this.actors) {
1044:       if (o === a || !o.alive || o.type !== 'enemy') continue;
1045:       const d = o.x - a.x;
1046:       if (Math.abs(d) < 55) sep -= Math.sign(d) * (1 - Math.abs(d) / 55);
1047:     }
1048:     a.vx = lerp(a.vx, moveDir * speed + sep * 90, 1 - Math.exp(-dt * 6));
1049:     a.x = clampX(a.x + a.vx * dt);
1050:     a.y = GROUND; a.onGround = true;
1051:     a.pose = null;
1052: 
1053:     // melee animation
1054:     if (a.meleeProgress >= 0) {
1055:       a.meleeProgress += dt / (a.enemyType === 'brute' ? 0.46 : 0.3);
1056:       if (a.meleeProgress > 0.52 && !a.swingHit) {
1057:         a.swingHit = true;
1058:         if (adx < (a.enemyType === 'brute' ? 105 : 86) && Math.abs(p.y - a.y) < 90) {
1059:           this.hurtPlayer(a.enemyType === 'brute' ? 26 : 13, p.x, p.y - 110, a.aim);
1060:           this.audio.flesh(true);
1061:         } else {
1062:           this.gore.dust(a.x + Math.cos(a.aim) * 60, a.y - 100, 2, 4);
1063:         }
1064:       }
1065:       if (a.meleeProgress >= 1) a.meleeProgress = -1;
1066:     }
1067: 
1068:     // attack decisions
1069:     if (a.attackCd <= 0) {
1070:       if (a.enemyType === 'gunner') {
1071:         if (adx < 950 && adx > 70 && Math.abs(dy) < 500) {
1072:           this.enemyShoot(a);
1073:           a.attackCd = rand(1.5, 0.75) * (this.wave > 6 ? 0.75 : 1);
1074:         }
1075:       } else {
1076:         const reach = a.enemyType === 'brute' ? 94 : 74;
1077:         if (adx < reach) {
1078:           a.meleeProgress = 0.001;
1079:           a.swingHit = false;
1080:           a.attackCd = a.enemyType === 'brute' ? 1.6 : 1.05;
1081:           this.audio.swing();
1082:           a.vx += dx > 0 ? 60 : -60;
1083:         } else {
1084:           a.attackCd = 0.2;
1085:         }
1086:       }
1087:     }
1088:     if (a.attackCd > 0) a.attackCd -= dt;
1089:     if (a.meleeProgress < 0) a.meleeProgress = -1;
1090:   }
1091: 
1092:   enemyShoot(a) {
1093:     const p = this.player;
1094:     const pose = a.pose;
1095:     if (!pose) return;
1096:     const hand = pose.handR;
